(function(){"use strict";if(document.readyState!=="loading"){throw new Error("Blogger embed must load synchronously during HTML parsing");}document.write("<div id=\"tpCalligraphyLibrary\">\n\n<style>\n#tpCalligraphyLibrary{\n    --ink:#29251f;\n    --soft:#665f56;\n    --brown:#86613b;\n    --dark:#604326;\n    --gold:#b39468;\n    --paper:#f7f2e8;\n    --light:#fffdf8;\n    --line:#e4dbcc;\n    --red:#a54135;\n    font-family:Georgia,\"Times New Roman\",serif;\n    color:var(--ink)\n}\n\n#tpCalligraphyLibrary,\n#tpCalligraphyLibrary *{\n    box-sizing:border-box\n}\n\n#tpCalligraphyLibrary button,\n#tpCalligraphyLibrary input{\n    font:inherit\n}\n\n\n/* =========================================================\n   LOGIN\n========================================================= */\n\n#tpCalligraphyLibrary .tp-login{\n    min-height:100vh;\n    display:flex;\n    justify-content:center;\n    align-items:flex-start;\n    padding:18px 12px;\n    background:var(--paper)\n}\n\n#tpCalligraphyLibrary .tp-login-box{\n    width:100%;\n    max-width:520px;\n    padding:30px 18px;\n    background:var(--light);\n    border:1px solid var(--line);\n    box-shadow:0 12px 35px rgba(70,52,30,.08);\n    text-align:center\n}\n\n#tpCalligraphyLibrary .tp-seal{\n    width:56px;\n    height:56px;\n    margin:0 auto 17px;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    border:1px solid var(--brown);\n    color:var(--brown);\n    font-size:26px\n}\n\n#tpCalligraphyLibrary .tp-eye{\n    color:var(--brown);\n    font-size:10px;\n    font-weight:700;\n    letter-spacing:2px\n}\n\n#tpCalligraphyLibrary .tp-login h2{\n    margin:8px 0 0;\n    font-size:27px\n}\n\n#tpCalligraphyLibrary .tp-desc{\n    max-width:430px;\n    margin:12px auto 19px;\n    color:var(--soft);\n    font-size:13px;\n    line-height:1.7\n}\n\n#tpCalligraphyLibrary .tp-login-form{\n    display:grid;\n    grid-template-columns:1fr;\n    gap:8px\n}\n\n#tpCalligraphyLibrary .tp-input{\n    width:100%;\n    height:47px;\n    padding:0 13px;\n    border:1px solid #e4dbcc;\n    background:#fff;\n    outline:0\n}\n\n#tpCalligraphyLibrary .tp-main-btn{\n    min-height:47px;\n    border:0;\n    background:var(--dark);\n    color:#fff;\n    cursor:pointer;\n    font-size:12px;\n    font-weight:700\n}\n\n#tpCalligraphyLibrary .tp-main-btn:disabled{\n    opacity:.6;\n    cursor:default\n}\n\n#tpCalligraphyLibrary .tp-msg{\n    min-height:19px;\n    margin-top:8px;\n    color:var(--red);\n    font-size:11.5px\n}\n\n\n/* =========================================================\n   UPGRADE\n========================================================= */\n\n#tpCalligraphyLibrary .tp-up-check{\n    display:none\n}\n\n#tpCalligraphyLibrary .tp-up-label{\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    gap:9px;\n    margin-top:18px;\n    padding-top:15px;\n    border-top:1px solid var(--line);\n    color:var(--dark);\n    cursor:pointer\n}\n\n#tpCalligraphyLibrary .tp-up-label small{\n    display:block;\n    color:var(--soft);\n    font-size:10px\n}\n\n#tpCalligraphyLibrary .tp-chev{\n    width:8px;\n    height:8px;\n    border-right:1px solid currentColor;\n    border-bottom:1px solid currentColor;\n    transform:rotate(45deg)\n}\n\n#tpCalligraphyLibrary .tp-up-check:checked + .tp-up-label .tp-chev{\n    transform:rotate(225deg)\n}\n\n#tpCalligraphyLibrary .tp-upgrade{\n    display:none;\n    margin-top:12px;\n    padding:15px;\n    border:1px solid var(--line);\n    background:#faf7f0;\n    text-align:left;\n    font-size:11.5px\n}\n\n#tpCalligraphyLibrary .tp-up-check:checked ~ .tp-upgrade{\n    display:block\n}\n\n#tpCalligraphyLibrary .tp-price{\n    display:flex;\n    justify-content:space-between;\n    margin:11px 0;\n    padding:9px 0;\n    border-top:1px dashed #e4dbcc;\n    border-bottom:1px dashed #e4dbcc\n}\n\n#tpCalligraphyLibrary .tp-price strong{\n    color:#a54135;\n    font-size:18px\n}\n\n#tpCalligraphyLibrary .tp-bank{\n    margin-top:11px;\n    padding:9px 11px;\n    border:1px solid var(--line);\n    background:#fff\n}\n\n#tpCalligraphyLibrary .tp-bank div{\n    display:flex;\n    justify-content:space-between;\n    gap:10px;\n    padding:5px 0;\n    border-bottom:1px dashed #eee4d7\n}\n\n#tpCalligraphyLibrary .tp-bank div:last-child{\n    border:0\n}\n\n#tpCalligraphyLibrary .tp-bank span{\n    color:var(--soft)\n}\n\n#tpCalligraphyLibrary .tp-red{\n    color:var(--red)\n}\n\n#tpCalligraphyLibrary .tp-qr{\n    text-align:center;\n    margin-top:13px\n}\n\n#tpCalligraphyLibrary .tp-qr img{\n    width:180px;\n    max-width:100%;\n    display:block;\n    margin:8px auto;\n    border:1px solid var(--line)\n}\n\n#tpCalligraphyLibrary .tp-note{\n    margin-top:11px;\n    padding:9px 10px;\n    border-left:3px solid var(--gold);\n    background:#fffaf1;\n    color:var(--soft);\n    line-height:1.6\n}\n\n#tpCalligraphyLibrary .tp-up-benefits{\n    margin:12px 0;\n    padding:12px;\n    border:1px solid var(--line);\n    background:#fff\n}\n\n#tpCalligraphyLibrary .tp-up-benefits-title{\n    margin-bottom:7px;\n    color:var(--dark);\n    font-weight:700\n}\n\n#tpCalligraphyLibrary .tp-up-benefit{\n    display:flex;\n    gap:8px;\n    padding:7px 0;\n    border-bottom:1px dashed #eee4d7\n}\n\n#tpCalligraphyLibrary .tp-up-benefit:last-child{\n    border:0\n}\n\n#tpCalligraphyLibrary .tp-up-benefit-icon{\n    width:19px;\n    height:19px;\n    flex:none;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    border:1px solid #d8c9b5;\n    border-radius:50%\n}\n\n\n/* =========================================================\n   LIBRARY\n========================================================= */\n\n#tpCalligraphyLibrary .tp-library{\n    display:none;\n    width:100%;\n    max-width:1220px;\n    margin:auto;\n    padding:12px;\n    background:var(--paper)\n}\n\n\n/* =========================================================\n   WELCOME\n========================================================= */\n\n#tpCalligraphyLibrary .tp-welcome{\n    display:none;\n    margin-bottom:13px;\n    padding:15px;\n    border:1px solid #d8c9b5;\n    background:var(--light)\n}\n\n#tpCalligraphyLibrary .tp-w-head{\n    display:flex;\n    align-items:flex-start;\n    justify-content:space-between;\n    gap:14px;\n    padding-bottom:12px;\n    border-bottom:1px solid #e4dbcc\n}\n\n\n/* =========================================================\n   TV4 - AVATAR + STUDENT IDENTITY\n========================================================= */\n\n#tpCalligraphyLibrary .tp-w-identity{\n    min-width:0;\n    flex:1;\n    display:flex;\n    align-items:center;\n    gap:10px\n}\n\n#tpCalligraphyLibrary .tp-w-avatar{\n    width:48px;\n    height:48px;\n    flex:0 0 48px;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    overflow:hidden;\n    border:1px solid #d8c9b5;\n    border-radius:50%;\n    background:#faf7f0;\n    color:#86613b;\n    font-size:20px\n}\n\n#tpCalligraphyLibrary .tp-w-avatar img{\n    width:100%;\n    height:100%;\n    display:block;\n    object-fit:cover\n}\n\n#tpCalligraphyLibrary .tp-w-user{\n    min-width:0;\n    flex:1\n}\n\n#tpCalligraphyLibrary .tp-w-small{\n    color:#86613b;\n    font-size:9px;\n    font-weight:700;\n    letter-spacing:1.5px\n}\n\n#tpCalligraphyLibrary .tp-w-name{\n    margin:4px 0 0;\n    font-size:18px\n}\n\n#tpCalligraphyLibrary .tp-w-code{\n    margin-top:4px;\n    color:#665f56;\n    font-size:10px\n}\n\n\n/* =========================================================\n   ASSETS\n========================================================= */\n\n#tpCalligraphyLibrary .tp-head-assets{\n    width:auto;\n    max-width:260px;\n    display:flex;\n    flex-direction:column;\n    align-items:flex-end;\n    gap:5px\n}\n\n#tpCalligraphyLibrary .tp-asset-label{\n    color:#86613b;\n    font-size:7px;\n    font-weight:700;\n    letter-spacing:.8px;\n    text-transform:uppercase\n}\n\n\n/* =========================================================\n   GEMS COMPACT\n========================================================= */\n\n#tpCalligraphyLibrary .tp-header-gems{\n    max-width:180px;\n    display:flex;\n    justify-content:flex-end;\n    align-items:center;\n    flex-wrap:wrap;\n    gap:3px\n}\n\n#tpCalligraphyLibrary .tp-head-gem{\n    display:inline-flex;\n    align-items:center;\n    gap:2px;\n    min-height:19px;\n    padding:2px 4px 2px 2px;\n    border:1px solid #e4dbcc;\n    border-radius:5px;\n    background:#faf7f0;\n    font-size:8px\n}\n\n#tpCalligraphyLibrary .tp-head-gem img{\n    width:13px;\n    height:13px;\n    object-fit:contain\n}\n\n#tpCalligraphyLibrary .tp-head-gem strong{\n    font-size:8px;\n    line-height:1\n}\n\n#tpCalligraphyLibrary .tp-no-gem{\n    padding:3px 5px;\n    border:1px solid #e4dbcc;\n    border-radius:5px;\n    color:#665f56;\n    font-size:8px\n}\n\n\n/* =========================================================\n   ITEMS\n========================================================= */\n\n#tpCalligraphyLibrary .tp-header-items{\n    width:100%;\n    max-width:260px;\n    display:flex;\n    justify-content:flex-end;\n    flex-wrap:wrap;\n    gap:4px\n}\n\n#tpCalligraphyLibrary .tp-head-item{\n    max-width:135px;\n    display:flex;\n    align-items:center;\n    gap:4px;\n    min-height:25px;\n    padding:3px 5px 3px 3px;\n    border:1px solid #e4dbcc;\n    border-radius:6px;\n    background:#fffdf8\n}\n\n#tpCalligraphyLibrary .tp-head-item-image{\n    width:18px;\n    height:18px;\n    flex:0 0 18px;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    overflow:hidden;\n    border:1px solid #eadfce;\n    border-radius:4px;\n    background:#faf7f0;\n    color:#86613b;\n    font-size:10px\n}\n\n#tpCalligraphyLibrary .tp-head-item-image img{\n    width:100%;\n    height:100%;\n    display:block;\n    object-fit:contain\n}\n\n#tpCalligraphyLibrary .tp-head-item-info{\n    min-width:0;\n    display:flex;\n    align-items:center;\n    gap:3px\n}\n\n#tpCalligraphyLibrary .tp-head-item-name{\n    max-width:88px;\n    overflow:hidden;\n    text-overflow:ellipsis;\n    white-space:nowrap;\n    color:#49392c;\n    font-size:7.5px;\n    line-height:1.2\n}\n\n#tpCalligraphyLibrary .tp-head-item-qty{\n    flex:none;\n    color:#a54135;\n    font-size:8px;\n    font-weight:700\n}\n\n#tpCalligraphyLibrary .tp-no-item{\n    padding:3px 5px;\n    border:1px solid #e4dbcc;\n    border-radius:5px;\n    color:#665f56;\n    font-size:8px\n}\n\n\n/* =========================================================\n   SUMMARY\n========================================================= */\n\n#tpCalligraphyLibrary .tp-summary{\n    display:grid;\n    grid-template-columns:1fr 1fr;\n    gap:7px;\n    margin-top:11px\n}\n\n#tpCalligraphyLibrary .tp-s-card{\n    padding:9px;\n    border:1px solid #e4dbcc;\n    background:#faf7f0\n}\n\n#tpCalligraphyLibrary .tp-s-card span{\n    display:block;\n    margin-bottom:3px;\n    color:#665f56;\n    font-size:9px\n}\n\n#tpCalligraphyLibrary .tp-w-title{\n    margin:15px 0 8px;\n    color:#604326;\n    font-size:11.5px;\n    font-weight:700\n}\n\n\n/* =========================================================\n   GIFTS\n========================================================= */\n\n#tpCalligraphyLibrary .tp-gifts{\n    display:grid;\n    grid-template-columns:1fr;\n    gap:7px\n}\n\n#tpCalligraphyLibrary .tp-gift{\n    display:flex;\n    gap:9px;\n    padding:10px;\n    border:1px solid #e4dbcc;\n    background:#faf7f0\n}\n\n#tpCalligraphyLibrary .tp-gift-icon{\n    width:38px;\n    height:38px;\n    flex:none;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    border:1px solid #d8c9b5;\n    background:#fff;\n    font-size:20px\n}\n\n#tpCalligraphyLibrary .tp-gift strong{\n    display:block;\n    margin-bottom:3px;\n    font-size:11.5px\n}\n\n#tpCalligraphyLibrary .tp-gift p{\n    margin:0;\n    color:#665f56;\n    font-size:10px\n}\n\n\n/* =========================================================\n   INTRO / SECTIONS\n========================================================= */\n\n#tpCalligraphyLibrary .tp-intro{\n    margin:25px 0;\n    padding:18px;\n    border:1px solid var(--line);\n    background:var(--light)\n}\n\n#tpCalligraphyLibrary .tp-intro h2{\n    margin:0 0 7px\n}\n\n#tpCalligraphyLibrary .tp-intro p{\n    margin:0;\n    color:#665f56;\n    font-size:12px;\n    line-height:1.7\n}\n\n#tpCalligraphyLibrary .tp-sec{\n    display:flex;\n    align-items:center;\n    gap:10px;\n    margin:32px 0 16px\n}\n\n#tpCalligraphyLibrary .tp-sec h2{\n    margin:0;\n    white-space:nowrap;\n    font-size:21px\n}\n\n#tpCalligraphyLibrary .tp-line{\n    height:1px;\n    flex:1;\n    background:#e4dbcc\n}\n\n\n/* =========================================================\n   VIDEOS\n========================================================= */\n\n#tpCalligraphyLibrary .tp-videos{\n    display:grid;\n    grid-template-columns:1fr;\n    gap:14px\n}\n\n#tpCalligraphyLibrary .tp-video{\n    overflow:hidden;\n    border:1px solid #e4dbcc;\n    background:#fffdf8\n}\n\n#tpCalligraphyLibrary .tp-video.low{\n    border-color:#d5b58a\n}\n\n#tpCalligraphyLibrary .tp-thumb{\n    position:relative;\n    aspect-ratio:16/9;\n    overflow:hidden;\n    background:#e5dfd5;\n    cursor:pointer;\n    touch-action:manipulation\n}\n\n#tpCalligraphyLibrary .tp-thumb img{\n    width:100%;\n    height:100%;\n    object-fit:cover;\n    pointer-events:none\n}\n\n#tpCalligraphyLibrary .tp-play{\n    position:absolute;\n    inset:0;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    pointer-events:none\n}\n\n#tpCalligraphyLibrary .tp-play:before{\n    content:\"\";\n    width:56px;\n    height:56px;\n    display:block;\n    border-radius:50%;\n    background:rgba(31,25,20,.82)\n}\n\n#tpCalligraphyLibrary .tp-play:after{\n    content:\"\";\n    position:absolute;\n    left:50%;\n    top:50%;\n    transform:translate(-38%,-50%);\n    width:0;\n    height:0;\n    border-top:9px solid transparent;\n    border-bottom:9px solid transparent;\n    border-left:14px solid #fff\n}\n\n#tpCalligraphyLibrary .tp-v-info{\n    padding:14px\n}\n\n#tpCalligraphyLibrary .tp-v-meta{\n    display:flex;\n    justify-content:space-between;\n    gap:7px\n}\n\n#tpCalligraphyLibrary .tp-lesson{\n    color:#86613b;\n    font-size:9px;\n    font-weight:700\n}\n\n#tpCalligraphyLibrary .tp-level-tag{\n    padding:4px 7px;\n    border-radius:99px;\n    background:#f2ebe0;\n    font-size:9px\n}\n\n#tpCalligraphyLibrary .tp-level-tag.high{\n    background:#fff0e4;\n    color:#a6542f\n}\n\n#tpCalligraphyLibrary .tp-v-info h3{\n    margin:6px 0;\n    font-size:17px\n}\n\n#tpCalligraphyLibrary .tp-v-info p{\n    margin:0;\n    color:#665f56;\n    font-size:11px\n}\n\n#tpCalligraphyLibrary .tp-watch{\n    margin-top:10px;\n    border:0;\n    background:none;\n    color:#604326;\n    cursor:pointer;\n    font-weight:700;\n    touch-action:manipulation\n}\n\n\n/* =========================================================\n   PAGES\n========================================================= */\n\n#tpCalligraphyLibrary .tp-pages{\n    display:none;\n    align-items:center;\n    justify-content:center;\n    gap:8px;\n    margin-top:18px\n}\n\n#tpCalligraphyLibrary .tp-page{\n    min-height:37px;\n    padding:0 12px;\n    border:1px solid #e4dbcc;\n    background:#fffdf8;\n    cursor:pointer\n}\n\n#tpCalligraphyLibrary .tp-page:disabled{\n    opacity:.35\n}\n\n\n/* =========================================================\n   DOCUMENTS\n========================================================= */\n\n#tpCalligraphyLibrary .tp-docs{\n    display:grid;\n    grid-template-columns:1fr;\n    gap:10px\n}\n\n#tpCalligraphyLibrary .tp-doc{\n    display:flex;\n    align-items:center;\n    gap:12px;\n    padding:14px;\n    border:1px solid #e4dbcc;\n    background:#fffdf8;\n    color:inherit;\n    text-decoration:none\n}\n\n#tpCalligraphyLibrary .tp-doc-icon{\n    width:45px;\n    height:45px;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    border:1px solid #b39468;\n    color:#86613b;\n    font-size:20px\n}\n\n\n/* =========================================================\n   STATUS\n========================================================= */\n\n#tpCalligraphyLibrary .tp-status{\n    grid-column:1/-1;\n    padding:30px 12px;\n    border:1px solid #e4dbcc;\n    background:#fffdf8;\n    color:#665f56;\n    text-align:center\n}\n\n#tpCalligraphyLibrary .tp-spinner{\n    width:28px;\n    height:28px;\n    margin:0 auto 10px;\n    border:2px solid #e4dbcc;\n    border-top-color:#86613b;\n    border-radius:50%;\n    animation:tpSpin .7s linear infinite\n}\n\n@keyframes tpSpin{\n    to{transform:rotate(360deg)}\n}\n\n\n/* =========================================================\n   WARNING\n========================================================= */\n\n#tpCalligraphyLibrary .tp-modal{\n    position:fixed;\n    inset:0;\n    z-index:999999;\n    display:none;\n    align-items:center;\n    justify-content:center;\n    padding:12px;\n    background:rgba(20,17,14,.82)\n}\n\n#tpCalligraphyLibrary .tp-modal.open{\n    display:flex\n}\n\n#tpCalligraphyLibrary .tp-warning{\n    width:100%;\n    max-width:440px;\n    padding:22px 18px;\n    border:1px solid #e4dbcc;\n    background:#fffdf8;\n    text-align:center\n}\n\n#tpCalligraphyLibrary .tp-score-box{\n    display:grid;\n    grid-template-columns:1fr 1fr;\n    gap:7px;\n    margin:13px 0\n}\n\n#tpCalligraphyLibrary .tp-score-box div{\n    padding:9px;\n    border:1px solid #e4dbcc;\n    background:#faf7f0\n}\n\n#tpCalligraphyLibrary .tp-warning-actions{\n    display:grid;\n    gap:7px\n}\n\n#tpCalligraphyLibrary .tp-warning-actions button{\n    min-height:41px;\n    border:0;\n    font-weight:700;\n    cursor:pointer;\n    touch-action:manipulation\n}\n\n#tpCalligraphyLibrary .tp-practice{\n    background:#604326;\n    color:#fff\n}\n\n#tpCalligraphyLibrary .tp-anyway{\n    background:#eee4d6\n}\n\n#tpCalligraphyLibrary .tp-cancel{\n    border:1px solid #e4dbcc!important;\n    background:#fff\n}\n\n\n/* =========================================================\n   MOBILE\n========================================================= */\n\n@media(max-width:649px){\n\n    #tpCalligraphyLibrary .tp-w-head{\n        gap:8px\n    }\n\n    #tpCalligraphyLibrary .tp-w-avatar{\n        width:42px;\n        height:42px;\n        flex-basis:42px\n    }\n\n    #tpCalligraphyLibrary .tp-w-identity{\n        gap:7px\n    }\n\n    #tpCalligraphyLibrary .tp-head-assets{\n        max-width:150px\n    }\n\n    #tpCalligraphyLibrary .tp-header-items{\n        max-width:150px\n    }\n\n    #tpCalligraphyLibrary .tp-head-item{\n        max-width:78px\n    }\n\n    #tpCalligraphyLibrary .tp-head-item-name{\n        max-width:43px\n    }\n}\n\n\n/* =========================================================\n   DESKTOP\n========================================================= */\n\n@media(min-width:650px){\n\n    #tpCalligraphyLibrary .tp-login{\n        align-items:center\n    }\n\n    #tpCalligraphyLibrary .tp-login-form{\n        grid-template-columns:1fr auto!important\n    }\n\n    #tpCalligraphyLibrary .tp-summary{\n        grid-template-columns:repeat(3,1fr)\n    }\n\n    #tpCalligraphyLibrary .tp-gifts{\n        grid-template-columns:1fr 1fr\n    }\n\n    #tpCalligraphyLibrary .tp-videos,\n    #tpCalligraphyLibrary .tp-docs{\n        grid-template-columns:repeat(2,1fr)\n    }\n}\n\n@media(min-width:980px){\n\n    #tpCalligraphyLibrary .tp-videos{\n        grid-template-columns:repeat(3,1fr)\n    }\n}\n\n/* TV4.1: card assets from the remaining canonical inventory. */\n#tpCalligraphyLibrary .tp-welcome.tp-has-background{\n    background-size:cover;background-position:center;background-repeat:no-repeat\n}\n#tpCalligraphyLibrary .tp-welcome.tp-has-background .tp-w-head,\n#tpCalligraphyLibrary .tp-welcome.tp-has-background .tp-summary,\n#tpCalligraphyLibrary .tp-welcome.tp-has-background .tp-score-box{\n    background:rgba(255,253,248,.9);border-radius:8px;padding:10px\n}\n#tpCalligraphyLibrary .tp-w-avatar{\n    position:relative;overflow:visible;border:0;background:transparent;isolation:isolate\n}\n#tpCalligraphyLibrary .tp-avatar-face{\n    width:100%;height:100%;display:flex;align-items:center;justify-content:center;\n    border:1px solid #d8c9b5;border-radius:50%;overflow:hidden;background:#faf7f0\n}\n#tpCalligraphyLibrary .tp-w-avatar img.tp-avatar-frame{\n    position:absolute;inset:-18%;width:136%;height:136%;max-width:none;\n    object-fit:contain;z-index:2;pointer-events:none;border:0;border-radius:0\n}\n#tpCalligraphyLibrary .tp-w-identity{gap:16px}\n#tpCalligraphyLibrary .tp-name-effect{position:relative;display:inline-flex;max-width:100%}\n#tpCalligraphyLibrary .tp-name-effect.reward-multitask-wrap{margin:10px 18px}\n#tpCalligraphyLibrary .reward-multitask-name{\n    animation:tpPotionColor 2.8s linear infinite,tpPotionGlow 1.6s ease-in-out infinite alternate\n}\n#tpCalligraphyLibrary .reward-multitask-star{\n    position:absolute;z-index:3;pointer-events:none;line-height:1;color:#fbbf24;\n    font-size:13px;text-shadow:0 0 6px #fff;animation:tpPotionStar 1.6s ease-in-out infinite\n}\n#tpCalligraphyLibrary .reward-multitask-star-left{left:-16px;top:-8px}\n#tpCalligraphyLibrary .reward-multitask-star-right{right:-16px;top:-8px;animation-delay:.35s}\n#tpCalligraphyLibrary .reward-multitask-star-bottom-left{left:-10px;bottom:-8px;animation-delay:.7s}\n#tpCalligraphyLibrary .reward-multitask-star-bottom-right{right:-10px;bottom:-8px;animation-delay:1.05s}\n@keyframes tpPotionColor{0%,100%{color:#b7791f}25%{color:#db2777}50%{color:#7c3aed}75%{color:#0284c7}}\n@keyframes tpPotionGlow{from{text-shadow:0 0 2px #fbbf24}to{text-shadow:0 0 8px #fbbf24}}\n@keyframes tpPotionStar{0%,100%{opacity:.35;transform:scale(.7)}50%{opacity:1;transform:scale(1.1)}}\n@media(prefers-reduced-motion:reduce){\n    #tpCalligraphyLibrary .reward-multitask-name,\n    #tpCalligraphyLibrary .reward-multitask-star{animation:none}\n}\n\n\n/* TV5: a quiet library, compact profile, separate replay and guide lists. */\n#tpCalligraphyLibrary{--paper:#f8f5ef;--light:#fffefa;--line:#e7dfd3;--dark:#514538}\n#tpCalligraphyLibrary .tp-library{max-width:1180px;padding:24px 16px 48px}\n#tpCalligraphyLibrary .tp-library-hero{padding:36px 26px;border:1px solid var(--line);border-radius:20px;background:linear-gradient(120deg,#eee7d8,#fffdf7);margin-bottom:18px}\n#tpCalligraphyLibrary .tp-library-hero .tp-eye{margin-bottom:12px}\n#tpCalligraphyLibrary .tp-library-hero h1{font-size:clamp(25px,5vw,38px);line-height:1.25;margin:0 0 12px;color:var(--dark)}\n#tpCalligraphyLibrary .tp-library-hero p{font-size:14px;line-height:1.8;max-width:680px;color:var(--soft);margin:0}\n#tpCalligraphyLibrary .tp-library-state{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px;font-family:Arial,sans-serif}\n#tpCalligraphyLibrary .tp-state-pill{padding:7px 12px;border-radius:99px;background:#fffefa;border:1px solid var(--line);font-size:11px}\n#tpCalligraphyLibrary .tp-profile-panel{display:none;margin:0 0 24px;border:1px solid var(--line);border-radius:12px;background:var(--light)}\n#tpCalligraphyLibrary .tp-profile-panel summary{cursor:pointer;padding:15px 18px;color:var(--dark);font-family:Arial,sans-serif;font-weight:700;font-size:13px}\n#tpCalligraphyLibrary .tp-profile-hint{font-size:10px;color:var(--soft);font-weight:400;margin-left:8px}\n#tpCalligraphyLibrary .tp-profile-panel .tp-welcome{border:0;border-top:1px solid var(--line);margin:0;border-radius:0 0 12px 12px}\n#tpCalligraphyLibrary .tp-intro{padding:20px 0;background:transparent;border:0}\n#tpCalligraphyLibrary .tp-sec{margin:28px 0 14px}\n#tpCalligraphyLibrary .tp-section-note{color:var(--soft);font-size:12px;line-height:1.7;margin:0 0 16px}\n#tpCalligraphyLibrary .tp-video{border-radius:14px;box-shadow:0 5px 18px rgba(65,48,29,.04)}\n#tpCalligraphyLibrary .tp-v-info{padding:17px}\n#tpCalligraphyLibrary .tp-v-info h3{line-height:1.45}\n#tpCalligraphyLibrary .tp-video.locked{background:#f2eee7}\n#tpCalligraphyLibrary .tp-video.locked .tp-thumb{cursor:default}\n#tpCalligraphyLibrary .tp-video.locked .tp-thumb img{filter:saturate(.25);opacity:.65}\n#tpCalligraphyLibrary .tp-video.locked .tp-play:before{background:#7b7265}\n#tpCalligraphyLibrary .tp-video.locked .tp-watch{background:#e6dfd3;color:#76694f;cursor:not-allowed}\n#tpCalligraphyLibrary .tp-doc{border-radius:12px}\n#tpCalligraphyLibrary .tp-pages{margin:18px 0 26px}\n@media(min-width:720px){#tpCalligraphyLibrary .tp-videos{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(min-width:1050px){#tpCalligraphyLibrary .tp-videos{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media(max-width:649px){#tpCalligraphyLibrary .tp-library{padding:14px 10px 32px}#tpCalligraphyLibrary .tp-library-hero{padding:26px 20px}#tpCalligraphyLibrary .tp-profile-hint{display:block;margin:5px 0 0 17px}}\n\n\n#tpCalligraphyLibrary .tp-upgrade-video-body{\n    display:flex;flex-direction:column;align-items:center;justify-content:center;\n    min-height:265px;padding:30px 22px;text-align:center;background:#f1ece3;height:100%\n}\n#tpCalligraphyLibrary .tp-upgrade-video-icon{font-size:30px;margin-bottom:16px}\n#tpCalligraphyLibrary .tp-upgrade-video-body h3{font-size:19px;line-height:1.55;margin:14px 0;color:var(--dark)}\n#tpCalligraphyLibrary .tp-upgrade-video-body p{font-size:12px;line-height:1.7;margin:0;color:var(--soft)}\n\n\n#tpCalligraphyLibrary .tp-card-payment{width:100%;margin-top:20px;padding-top:18px;border-top:1px solid #d8c9b5;text-align:left;font-family:Arial,sans-serif;font-size:11px}\n#tpCalligraphyLibrary .tp-card-payment>strong{display:block;line-height:1.6;color:var(--dark)}\n#tpCalligraphyLibrary .tp-card-payment-row{display:flex;flex-wrap:wrap;justify-content:space-between;gap:5px;padding:7px 0;border-bottom:1px dashed #e0d7c9}\n#tpCalligraphyLibrary .tp-card-payment-row strong{overflow-wrap:anywhere}\n#tpCalligraphyLibrary .tp-card-payment p{margin:12px 0 5px;font-size:11px}\n#tpCalligraphyLibrary .tp-card-payment .tp-card-transfer-info{color:var(--red);overflow-wrap:anywhere}\n#tpCalligraphyLibrary .tp-card-upgrade-qr{display:block;width:190px;max-width:100%;height:auto;margin:12px auto;border:1px solid var(--line);border-radius:8px}\n#tpCalligraphyLibrary .tp-card-payment-note{line-height:1.7}\n\n</style>\n\n\n<!--=========================================================\n     LOGIN\n=========================================================-->\n\n<div class=\"tp-login\" id=\"tpLoginScreen\">\n\n<div class=\"tp-login-box\">\n\n<div class=\"tp-seal\">\u66f8</div>\n\n<div class=\"tp-eye\">THANH PHONG TH\u01af M\u00d4N</div>\n\n<h2>Kho t\u00e0i li\u1ec7u h\u1ecdc vi\u00ean</h2>\n\n<p class=\"tp-desc\">\nNh\u1eadp M\u00e3 h\u1ecdc vi\u00ean ho\u1eb7c M\u00e3 tr\u1ee3 gi\u1ea3ng \u0111\u1ec3 xem th\u01b0 vi\u1ec7n video v\u00e0 b\u00e0i gi\u1ea3ng theo kh\u00f3a.\n</p>\n\n<div class=\"tp-login-form\">\n\n<input autocomplete=\"off\" class=\"tp-input\" id=\"tpPasswordInput\" onkeydown=\"tpPasswordKey(event)\" placeholder=\"Nh\u1eadp M\u00e3 h\u1ecdc vi\u00ean...\" type=\"text\" />\n\n<button class=\"tp-main-btn\" id=\"tpLoginButton\" onclick=\"tpLogin()\" type=\"button\">\n\u0110\u0103ng nh\u1eadp\n</button>\n\n</div>\n\n<div class=\"tp-msg\" id=\"tpPasswordMessage\"></div>\n\n\n<input class=\"tp-up-check\" id=\"tpUpgradeCheck\" type=\"checkbox\" />\n\n<label class=\"tp-up-label\" for=\"tpUpgradeCheck\" onclick=\"tpUpdateQR()\">\n\n<span>\n<small>Mu\u1ed1n xem th\u00eam video tr\u1ea3 ph\u00ed?</small>\n<strong>N\u00e2ng c\u1ea5p t\u00e0i kho\u1ea3n</strong>\n</span>\n\n<span class=\"tp-chev\"></span>\n\n</label>\n\n\n<div class=\"tp-upgrade\">\n\n<p>\nH\u1ecdc vi\u00ean trong HocVien v\u00e0 tr\u1ee3 gi\u1ea3ng trong TroGiang \u0111\u1ec1u c\u00f3 th\u1ec3 v\u00e0o th\u01b0 vi\u1ec7n. Tr\u1ee3 gi\u1ea3ng \u0111\u01b0\u1ee3c xem video tr\u1ea3 ph\u00ed nh\u01b0 h\u1ecdc vi\u00ean c\u00f3 g\u00f3i n\u00e2ng c\u1ea5p.\n</p>\n\n<div class=\"tp-up-benefits\">\n\n<div class=\"tp-up-benefits-title\">\nT\u00e0i kho\u1ea3n n\u00e2ng c\u1ea5p \u0111\u01b0\u1ee3c:\n</div>\n\n<div class=\"tp-up-benefit\">\n<span class=\"tp-up-benefit-icon\">\u2713</span>\n<span>Quy\u1ec1n \u01b0u ti\u00ean nh\u1eadn x\u00e9t b\u00e0i t\u1eadp</span>\n</div>\n\n<div class=\"tp-up-benefit\">\n<span class=\"tp-up-benefit-icon\">\u2713</span>\n<span>Xem l\u1ea1i b\u00e0i gi\u1ea3ng c\u1ee7a kh\u00f3a \u0111ang theo h\u1ecdc</span>\n</div>\n\n<div class=\"tp-up-benefit\">\n<span class=\"tp-up-benefit-icon\">\u2713</span>\n<span>M\u1edf kho\u00e1 to\u00e0n b\u1ed9 video h\u01b0\u1edbng d\u1eabn c\u00e1c b\u00e0i</span>\n</div>\n\n</div>\n\n<div class=\"tp-price\">\n<span>Ph\u00ed n\u00e2ng c\u1ea5p</span>\n<strong>800.000\u0111</strong>\n</div>\n\n<input class=\"tp-input\" id=\"tpUpgradePhone\" oninput=\"tpScheduleQR()\" placeholder=\"Nh\u1eadp S\u0110T Zalo\" type=\"tel\" />\n\n<div class=\"tp-bank\">\n\n<div>\n<span>Ng\u00e2n h\u00e0ng</span>\n<strong>MB Bank</strong>\n</div>\n\n<div>\n<span>S\u1ed1 t\u00e0i kho\u1ea3n</span>\n<strong>0530113118888</strong>\n</div>\n\n<div>\n<span>Ch\u1ee7 t\u00e0i kho\u1ea3n</span>\n<strong>BUI KHAC SANG</strong>\n</div>\n\n<div>\n<span>S\u1ed1 ti\u1ec1n</span>\n<strong class=\"tp-red\">800.000\u0111</strong>\n</div>\n\n<div>\n<span>N\u1ed9i dung CK</span>\n<strong class=\"tp-red\" id=\"tpTransferSyntax\">HOCTHUPHAP [S\u0110T]</strong>\n</div>\n\n</div>\n\n<div class=\"tp-qr\">\n\n<img alt=\"VietQR\" id=\"tpQrImage\" src=\"https://img.vietqr.io/image/MB-0530113118888-compact2.png?amount=800000&amp;addInfo=HOCTHUPHAP&amp;accountName=BUI%20KHAC%20SANG\" />\n\n<div id=\"tpQrStatus\">\nNh\u1eadp S\u0110T \u0111\u1ec3 c\u1eadp nh\u1eadt QR.\n</div>\n\n</div>\n\n<div class=\"tp-note\">\nSau khi \u0111\u01b0\u1ee3c x\u00e9t duy\u1ec7t v\u00e0o g\u00f3i n\u00e2ng c\u1ea5p, M\u00e3 h\u1ecdc vi\u00ean s\u1ebd \u0111\u01b0\u1ee3c m\u1edf th\u00eam video tr\u1ea3 ph\u00ed.\n</div>\n\n</div>\n\n</div>\n</div>\n\n\n<!--=========================================================\n     LIBRARY\n=========================================================-->\n\n<div class=\"tp-library\" id=\"tpLibraryContent\">\n<header class=\"tp-library-hero\">\n    <div class=\"tp-eye\">THANH PHONG TH\u01af M\u00d4N</div>\n    <h1>H\u1ecdc t\u1eeb n\u00e9t b\u00fat, v\u1eefng t\u1eebng ng\u00e0y</h1>\n    <p>Kh\u00f4ng gian b\u00e0i gi\u1ea3ng, h\u01b0\u1edbng d\u1eabn v\u00e0 t\u00e0i li\u1ec7u d\u00e0nh cho h\u00e0nh tr\u00ecnh luy\u1ec7n ch\u1eef c\u1ee7a b\u1ea1n.</p>\n    <div class=\"tp-library-state\" id=\"tpLibraryState\"></div>\n</header>\n<details class=\"tp-profile-panel\" id=\"tpProfilePanel\">\n    <summary><span>Th\u00f4ng tin h\u1ecdc vi\u00ean</span><span class=\"tp-profile-hint\">Nh\u1ea5n \u0111\u1ec3 m\u1edf / thu g\u1ecdn</span></summary>\n\n\n<div class=\"tp-welcome\" id=\"tpStudentWelcome\">\n\n<div class=\"tp-w-head\">\n\n\n<!--TV4: AVATAR + NAME-->\n\n<div class=\"tp-w-identity\">\n\n<div class=\"tp-w-avatar\" id=\"tpStudentAvatar\">\n\u66f8\n</div>\n\n<div class=\"tp-w-user\">\n\n<div class=\"tp-w-small\">\nCH\u00c0O M\u1eeaNG H\u1eccC VI\u00caN\n</div>\n\n<h3 class=\"tp-w-name\" id=\"tpWelcomeName\">\n\u0110ang t\u1ea3i...\n</h3>\n\n<div class=\"tp-w-code\" id=\"tpWelcomeCode\"></div>\n\n</div>\n\n</div>\n\n\n<!--ASSETS-->\n\n<div class=\"tp-head-assets\">\n\n<div class=\"tp-asset-label\">\nLinh th\u1ea1ch\n</div>\n\n<div class=\"tp-header-gems\" id=\"tpHeaderGems\">\n<span class=\"tp-no-gem\">\u0110ang t\u1ea3i...</span>\n</div>\n\n<div class=\"tp-asset-label\">\nV\u1eadt ph\u1ea9m\n</div>\n\n<div class=\"tp-header-items\" id=\"tpHeaderItems\">\n<span class=\"tp-no-item\">\u0110ang t\u1ea3i...</span>\n</div>\n\n</div>\n\n</div>\n\n\n<div class=\"tp-summary\">\n\n<div class=\"tp-s-card\">\n<span>Rank hi\u1ec7n t\u1ea1i</span>\n<strong id=\"tpWelcomePoints\">...</strong>\n</div>\n\n<div class=\"tp-s-card\">\n<span>T\u1ed5ng linh th\u1ea1ch</span>\n<strong id=\"tpWelcomeGemTotal\">...</strong>\n</div>\n\n<div class=\"tp-s-card\">\n<span>Danh hi\u1ec7u</span>\n<strong id=\"tpWelcomeTitle\">...</strong>\n</div>\n\n</div>\n\n<div class=\"tp-w-title\">\nQu\u00e0 th\u00e0nh t\u00edch\n</div>\n\n<div class=\"tp-gifts\" id=\"tpGiftGrid\"></div>\n\n</div>\n\n\n</details>\n\n<div class=\"tp-intro\">\n<h2>M\u1ed7i l\u1ea7n xem, m\u1ed9t l\u1ea7n luy\u1ec7n</h2>\n<p>\nH\u00e3y h\u1ecdc theo t\u1eebng c\u1ea5p \u0111\u1ed9, luy\u1ec7n t\u1eadp \u0111\u1ec1u \u0111\u1eb7n v\u00e0 n\u1ed9p b\u00e0i \u0111\u1ec3 t\u00edch l\u0169y \u0111i\u1ec3m kinh nghi\u1ec7m.\n</p>\n</div>\n\n\n<section class=\"tp-replay-section\">\n<div class=\"tp-sec\">\n<small>01</small>\n<h2>Video xem l\u1ea1i</h2>\n<span class=\"tp-line\"></span>\n</div>\n<p class=\"tp-section-note\" id=\"tpReplayNote\">B\u00e0i gi\u1ea3ng d\u00e0nh cho kh\u00f3a \u0111ang theo h\u1ecdc.</p>\n<div class=\"tp-videos\" id=\"tpReplayGrid\"><div class=\"tp-status\">\u0110ang t\u1ea3i b\u00e0i gi\u1ea3ng...</div></div>\n<div class=\"tp-pages\" id=\"tpReplayPages\"></div>\n</section>\n\n<div class=\"tp-sec\">\n<small>02</small>\n<h2>Video h\u01b0\u1edbng d\u1eabn</h2>\n<span class=\"tp-line\"></span>\n</div>\n\n<div class=\"tp-videos\" id=\"tpVideoGrid\">\n\n<div class=\"tp-status\">\n<div class=\"tp-spinner\"></div>\n\u0110ang t\u1ea3i th\u01b0 vi\u1ec7n video...\n</div>\n\n</div>\n\n<div class=\"tp-pages\" id=\"tpVideoPages\"></div>\n\n\n<div class=\"tp-sec\">\n<small>03</small>\n<h2>T\u00e0i li\u1ec7u tham kh\u1ea3o</h2>\n<span class=\"tp-line\"></span>\n</div>\n\n\n<div class=\"tp-docs\">\n\n<a class=\"tp-doc\" id=\"tpPaidReferenceBook\" hidden style=\"display:none\" rel=\"noopener\" target=\"_blank\">\n\n<div class=\"tp-doc-icon\">\u6587</div>\n\n<div>\n<h3>S\u00e1ch Th\u01b0 ph\u00e1p Vi\u1ec7t \u2013 Quy\u1ec3n 1</h3>\n<p>Ki\u1ebfn th\u1ee9c d\u00e0nh cho ng\u01b0\u1eddi m\u1edbi b\u1eaft \u0111\u1ea7u.</p>\n</div>\n\n</a>\n\n\n<a class=\"tp-doc\" href=\"thu-vien-lam-mo.html\">\n\n<div class=\"tp-doc-icon\">\u66f8</div>\n\n<div>\n<h3>M\u1eabu ch\u1eef tham kh\u1ea3o</h3>\n<p>Tham kh\u1ea3o b\u1ed1 c\u1ee5c, n\u00e9t ch\u1eef v\u00e0 ph\u01b0\u01a1ng ph\u00e1p l\u00e2m m\u00f4.</p>\n</div>\n\n</a>\n\n</div>\n\n</div>\n\n\n<!--=========================================================\n     WARNING\n=========================================================-->\n\n<div class=\"tp-modal\" id=\"tpWarningModal\" onclick=\"tpWarningOutside(event)\">\n\n<div class=\"tp-warning\">\n\n<h3>Th\u1eed th\u00e1ch cao h\u01a1n \u0111ang ch\u1edd b\u1ea1n</h3>\n\n<p id=\"tpWarningText\"></p>\n\n<div class=\"tp-score-box\">\n\n<div>\n<span>Rank hi\u1ec7n t\u1ea1i</span>\n<strong id=\"tpCurrentPoints\">0</strong>\n</div>\n\n<div>\n<span>Rank khuy\u1ebfn ngh\u1ecb</span>\n<strong id=\"tpRequiredPoints\">0</strong>\n</div>\n\n</div>\n\n<p>\nB\u1ea1n n\u00ean luy\u1ec7n t\u1eadp th\u00eam tr\u01b0\u1edbc khi h\u1ecdc b\u00e0i n\u00e0y.\n\u0110\u00e2y ch\u1ec9 l\u00e0 khuy\u1ebfn ngh\u1ecb v\u00e0 kh\u00f4ng kh\u00f3a n\u1ed9i dung.\n</p>\n\n<div class=\"tp-warning-actions\">\n\n<button class=\"tp-practice\" onclick=\"tpGoPractice()\" type=\"button\">\nL\u00e0m b\u00e0i t\u1eadp \u0111\u1ec3 t\u0103ng Rank\n</button>\n\n<button class=\"tp-anyway\" onclick=\"tpWatchAnyway()\" type=\"button\">\nT\u00f4i v\u1eabn mu\u1ed1n xem\n</button>\n\n<button class=\"tp-cancel\" onclick=\"tpCloseWarning()\" type=\"button\">\n\u0110\u1ec3 sau\n</button>\n\n</div>\n\n</div>\n</div>\n\n\n<script>\n\nwindow.OCDMinhHongPageContext=\"personal\";\nwindow.OCDMinhHongContentTab=\"ThuVien\";\n\n\n(function(){\n\n\"use strict\";\n\n\n/* =========================================================\n   APP\n========================================================= */\n\nvar APP={\n\n    PASSWORD:\"123456\",\n\n    SHEET_ID:\n    \"1hLNi_OP6ScSz8OUH-Qj7qc5LTTPAHevZQg9MvFBvVro\",\n\n    SHEET_GID:\"0\",\n\n    PRIORITY_SHEET_GID:\"705559221\",\n\n    ASSISTANT_CSV:\n    \"https://docs.google.com/spreadsheets/d/10EjfikAuPyc1t_aGDDsUlq0eewo0WUl5qOyXjkVG28M/gviz/tq?gid=1767609121&headers=1&tqx=out:csv&range=B:E\",\n\n    STUDENT_REGISTRY:\n    \"https://docs.google.com/spreadsheets/d/1GJoTRsbq0kZfZrDdh0uCC667PwS3Bgkje2fHQnwnCKs/export?format=csv&gid=1603096683\",\n\n    STUDENT_REGISTRY_FALLBACK:\n    \"https://docs.google.com/spreadsheets/d/e/2PACX-1vRP5cc8duj1XrCXMrymo6Cj7aqIkWfX6bHxGeW-lXcSewfQXhM8fZ5rzbNIQ9mBeVuB8yYr_o1aBoYA/pub?gid=1603096683&single=true&output=csv\",\n\n    RANKING:\n    \"https://docs.google.com/spreadsheets/d/e/2PACX-1vRP5cc8duj1XrCXMrymo6Cj7aqIkWfX6bHxGeW-lXcSewfQXhM8fZ5rzbNIQ9mBeVuB8yYr_o1aBoYA/pub?gid=1326884435&single=true&output=csv\",\n\n    SUBMISSIONS:\n    \"https://docs.google.com/spreadsheets/d/e/2PACX-1vRP5cc8duj1XrCXMrymo6Cj7aqIkWfX6bHxGeW-lXcSewfQXhM8fZ5rzbNIQ9mBeVuB8yYr_o1aBoYA/pub?output=csv\",\n\n    DELETE_LOG:\n    \"https://docs.google.com/spreadsheets/d/1GJoTRsbq0kZfZrDdh0uCC667PwS3Bgkje2fHQnwnCKs/export?format=csv&gid=521976322\",\n\n    FORM:\n    \"https://forms.gle/Af3jRUYfUD9try9h8\",\n\n    PAGE_SIZE:6,\n\n    DIFFICULTY_STEP:5,\n\n    loginMode:\"\",\n    pendingCode:\"\",\n    currentCode:\"\",\n    loginCompleted:false,\n\n    student:null,\n    profile:null,\n\n    videos:[],\n    replays:[],\n    page:1,\n    replayPage:1,\n    permissionLoaded:false,\n    upgradeCode:\"\",\n\n    pendingVideo:null,\n    currentVideo:null,\n\n    accessCodes:null,\n    priorityCodes:null,\n\n    assistantMap:null,\n    assistantPromise:null,\n    assistantLoadedAt:0,\n\n    registryMap:null,\n    registryPromise:null,\n    registryLoadedAt:0,\n    legacyMap:null,\n\n    validSubmissionCsv:\"\",\n\n    profileRefreshing:false,\n\n    autoLoginRunning:false,\n    autoLoginFinished:false,\n    autoLoginCode:\"\"\n\n};\n\n\n/* =========================================================\n   LEVELS\n========================================================= */\n\nvar LEVELS=[\n    {min:0,name:\"T\u00e2n th\u1ee7 nh\u1eadp m\u00f4n\"},\n    {min:100,name:\"C\u1ea7m b\u00fat ch\u1eafc ch\u1eafn\"},\n    {min:300,name:\"Bi\u1ebft c\u00e1ch l\u1ea5y m\u1ef1c\"},\n    {min:700,name:\"L\u1ed9 phong \u0111\u1ec1u \u0111\u1eb7n\"},\n    {min:1500,name:\"Trung phong s\u1eafc n\u00e9t\"},\n    {min:3000,name:\"Nh\u00e3n l\u1ef1c n\u00e2ng cao\"},\n    {min:5000,name:\"Ch\u01b0\u01a1ng ph\u00e1p \u1ed5n \u0111\u1ecbnh\"},\n    {min:8000,name:\"Cao th\u1ee7\"},\n    {min:12000,name:\"Tho\u00e1t t\u1ee5c t\u1ef1 nhi\u00ean\"},\n    {min:20000,name:\"Th\u01b0 gia t\u1ed1 ch\u1ea5t\"}\n];\n\n\n/* =========================================================\n   HELPERS\n========================================================= */\n\nfunction id(x){\n    return document.getElementById(x);\n}\n\nfunction trim(v){\n    return String(v==null?\"\":v).trim();\n}\n\nfunction norm(v){\n    return trim(v)\n        .replace(/[\\uFEFF\\u200B-\\u200D\\u2060]/g,\"\")\n        .replace(/\\s+/g,\"\")\n        .toUpperCase();\n}\n\nfunction nt(v){\n    return trim(v)\n        .toLowerCase()\n        .normalize(\"NFD\")\n        .replace(/[\\u0300-\\u036f]/g,\"\")\n        .replace(/\u0111/g,\"d\")\n        .replace(/\\s+/g,\" \");\n}\n\n\n/* =========================================================\n   TV4 - CLEAN ITEM DISPLAY NAME\n\n   S\u1eeda tr\u01b0\u1eddng h\u1ee3p Blogger / d\u1eef li\u1ec7u c\u0169 tr\u1ea3:\n   &#215;\n   &times;\n\n   th\u00e0nh k\u00fd t\u1ef1 Unicode th\u1eadt.\n========================================================= */\n\nfunction cleanItemDisplayName(value){\n\n    return trim(\n        String(value==null?\"\":value)\n\n        .replace(\n            /&#0*215;|&#x0*d7;|&times;/gi,\n            String.fromCharCode(215)\n        )\n    );\n}\n\n\n/* =========================================================\n   CSV\n========================================================= */\n\nfunction csv(t){\n\n    t=String(t||\"\")\n        .replace(/^\\uFEFF/,\"\");\n\n    var a=[];\n    var r=[];\n    var f=\"\";\n    var q=false;\n\n    for(var i=0;i<t.length;i++){\n\n        var c=t[i];\n\n        if(c=='\"'){\n\n            if(q && t[i+1]=='\"'){\n                f+='\"';\n                i++;\n            }else{\n                q=!q;\n            }\n\n        }else if(c==\",\"&&!q){\n\n            r.push(f);\n            f=\"\";\n\n        }else if((c==\"\\n\"||c==\"\\r\")&&!q){\n\n            if(c==\"\\r\"&&t[i+1]==\"\\n\"){\n                i++;\n            }\n\n            r.push(f);\n\n            if(r.some(x=>trim(x)!==\"\")){\n                a.push(r);\n            }\n\n            r=[];\n            f=\"\";\n\n        }else{\n\n            f+=c;\n        }\n    }\n\n    r.push(f);\n\n    if(r.some(x=>trim(x)!==\"\")){\n        a.push(r);\n    }\n\n    return a;\n}\n\n\n/* =========================================================\n   COLUMN\n========================================================= */\n\nfunction col(h,aliases){\n\n    var n=h.map(nt);\n\n    for(var a of aliases){\n\n        var x=n.indexOf(nt(a));\n\n        if(x>=0){\n            return x;\n        }\n    }\n\n    for(var a2 of aliases){\n\n        var w=nt(a2);\n\n        for(var i=0;i<n.length;i++){\n\n            if(w && n[i].indexOf(w)>=0){\n                return i;\n            }\n        }\n    }\n\n    return -1;\n}\n\n\n/* =========================================================\n   FETCH\n========================================================= */\n\nasync function fetchText(url){\n    var controller=typeof AbortController!==\"undefined\"?new AbortController():null;\n    var timer=controller?setTimeout(function(){controller.abort();},12000):null;\n    try{\n        var response=await fetch(url+(url.includes(\"?\")?\"&\":\"?\")+\"_=\"+Date.now(),\n            {cache:\"no-store\",signal:controller?controller.signal:undefined});\n        if(!response.ok) throw new Error(\"HTTP \"+response.status);\n        var text=await response.text();\n        if(/^\\s*(?:<!doctype|<html)/i.test(text)) throw new Error(\"Ngu\u1ed3n d\u1eef li\u1ec7u tr\u1ea3 trang HTML thay v\u00ec CSV.\");\n        return text;\n    }finally{if(timer!==null) clearTimeout(timer);}\n}\n\n\n/* =========================================================\n   WAIT CORE\n========================================================= */\n\nfunction waitCore(){\n\n    return new Promise((resolve,reject)=>{\n\n        var n=0;\n\n        var t=setInterval(()=>{\n\n            var R=window.StudentRewardSystem;\n\n            if(\n                R &&\n                R.version &&\n                typeof R.getStudentRewardProfile===\"function\" &&\n                typeof R.fetchCSV===\"function\" &&\n                typeof R.parseCSV===\"function\"\n            ){\n\n                clearInterval(t);\n                resolve(R);\n\n            }else if(++n>=200){\n\n                clearInterval(t);\n\n                reject(\n                    Error(\n                        \"Kh\u00f4ng t\u00ecm th\u1ea5y StudentRewardSystem Core canonical.\"\n                    )\n                );\n            }\n\n        },50);\n\n    });\n}\n\n\n/* =========================================================\n   STUDENT DIRECTORY\n========================================================= */\n\nfunction studentDirectoryFromRows(rows){\n    var header=-1;\n    for(var i=0;i<Math.min((rows || []).length,10);i++){\n        if(col(rows[i],[\"m\u00e3 h\u1ecdc vi\u00ean\",\"ma hoc vien\"])>=0){header=i;break;}\n    }\n    if(header<0) throw new Error(\"Kh\u00f4ng \u0111\u1ecdc \u0111\u01b0\u1ee3c c\u1ed9t M\u00e3 h\u1ecdc vi\u00ean c\u1ee7a tab HocVien.\");\n    var h=rows[header];\n    var cc=col(h,[\"m\u00e3 h\u1ecdc vi\u00ean\",\"ma hoc vien\"]);\n    var nc=col(h,[\"h\u1ecd v\u00e0 t\u00ean\",\"ho va ten\",\"h\u1ecd t\u00ean\",\"ho ten\"]);\n    var gc=col(h,[\"t\u1ed5\",\"to\"]),kc=col(h,[\"kh\u00f3a\",\"kho\u00e1\",\"khoa\"]),sc=col(h,[\"tr\u1ea1ng th\u00e1i\",\"trang thai\"]);\n    var map=new Map();\n    rows.slice(header+1).forEach(function(row){\n        var code=norm(row[cc]);\n        if(code) map.set(code,{code:code,name:nc>=0?trim(row[nc]):\"\",\n            group:gc>=0?trim(row[gc]):\"\",course:kc>=0?trim(row[kc]):\"\",\n            status:sc>=0?norm(row[sc]):\"\",identitySource:\"HocVien\"});\n    });\n    return map;\n}\n\nasync function loadDirectory(url,forceRefresh){\n    var R=window.StudentRewardSystem;\n    var errors=[];\n    if(R && typeof R.loadStudentRegistry===\"function\"){\n        try{\n            var registry=await R.loadStudentRegistry(Boolean(forceRefresh));\n            if(registry && registry.studentMap && registry.studentMap.size){\n                var mapped=new Map();\n                registry.studentMap.forEach(function(student,code){\n                    var key=norm(code);\n                    if(key) mapped.set(key,Object.assign({},student,{code:key,identitySource:\"HocVien\"}));\n                });\n                return mapped;\n            }\n        }catch(error){errors.push(error);}\n    }\n    var urls=[url,APP.STUDENT_REGISTRY_FALLBACK].filter(Boolean);\n    for(var i=0;i<urls.length;i++){\n        try{\n            var rows;\n            if(R && typeof R.fetchRows===\"function\"){\n                rows=await R.fetchRows(urls[i]);\n            }else{\n                rows=csv(await fetchText(urls[i]));\n            }\n            var result=studentDirectoryFromRows(rows);\n            if(!result.size) throw new Error(\"Tab HocVien ch\u01b0a tr\u1ea3 v\u1ec1 m\u00e3 h\u1ecdc vi\u00ean.\");\n            return result;\n        }catch(error){errors.push(error);}\n    }\n    throw new Error(\"Ch\u01b0a t\u1ea3i \u0111\u01b0\u1ee3c danh s\u00e1ch HocVien. \"+(errors.length?errors[errors.length-1].message:\"\"));\n}\n\nasync function ensureStudentDirectory(forceRefresh){\n    if(APP.registryPromise) return APP.registryPromise;\n    if(!forceRefresh && APP.registryMap && APP.registryMap.size && Date.now()-APP.registryLoadedAt<15000){\n        return APP.registryMap;\n    }\n    var task=loadDirectory(APP.STUDENT_REGISTRY,forceRefresh).then(function(map){\n        APP.registryMap=map;\n        APP.registryLoadedAt=Date.now();\n        return map;\n    });\n    APP.registryPromise=task;\n    try{return await task;}finally{if(APP.registryPromise===task) APP.registryPromise=null;}\n}\n\n\n/* =========================================================\n   FIND STUDENT\n========================================================= */\n\nfunction assistantDirectoryFromRows(rows){\n    var header=-1;\n    for(var i=0;i<Math.min((rows || []).length,10);i++){\n        if(col(rows[i],[\"m\u00e3 h\u1ecdc vi\u00ean\",\"ma hoc vien\"])>=0){header=i;break;}\n    }\n    if(header<0) throw new Error(\"Kh\u00f4ng \u0111\u1ecdc \u0111\u01b0\u1ee3c c\u1ed9t M\u00e3 h\u1ecdc vi\u00ean c\u1ee7a tab TroGiang.\");\n    var h=rows[header],cc=col(h,[\"m\u00e3 h\u1ecdc vi\u00ean\",\"ma hoc vien\"]);\n    var nc=col(h,[\"h\u1ecd v\u00e0 t\u00ean\",\"ho va ten\",\"h\u1ecd t\u00ean\",\"ho ten\"]);\n    var kc=col(h,[\"b\u1ea1n t\u1ed1t nghi\u1ec7p kho\u00e1 m\u1ea5y?\",\"ban tot nghiep khoa may\"]);\n    var gc=col(h,[\"t\u1ed5 b\u1ea1n mu\u1ed1n ph\u1ee5 tr\u00e1ch\",\"to ban muon phu trach\"]);\n    var map=new Map();\n    rows.slice(header+1).forEach(function(row){\n        var code=norm(row[cc]);\n        if(code) map.set(code,{code:code,name:nc>=0?trim(row[nc]):\"\",\n            course:kc>=0?trim(row[kc]):\"\",group:gc>=0?trim(row[gc]):\"\",\n            identitySource:\"TroGiang\",isAssistant:true});\n    });\n    return map;\n}\n\nasync function ensureAssistantDirectory(forceRefresh){\n    if(APP.assistantPromise) return APP.assistantPromise;\n    if(!forceRefresh && APP.assistantMap && Date.now()-APP.assistantLoadedAt<15000) return APP.assistantMap;\n    var task=fetchText(APP.ASSISTANT_CSV).then(function(text){\n        var map=assistantDirectoryFromRows(csv(text));\n        APP.assistantMap=map;APP.assistantLoadedAt=Date.now();return map;\n    }).catch(function(error){APP.assistantMap=null;throw error;});\n    APP.assistantPromise=task;\n    try{return await task;}finally{if(APP.assistantPromise===task) APP.assistantPromise=null;}\n}\n\nfunction isAssistantCode(code){\n    return Boolean(APP.assistantMap && APP.assistantMap.has(norm(code)));\n}\n\nasync function findStudent(code){\n    code=norm(code);\n    var results=await Promise.allSettled([ensureStudentDirectory(false),ensureAssistantDirectory(false)]);\n    function matched(){\n        var student=APP.registryMap && APP.registryMap.get(code);\n        if(student) return Object.assign({},student,{isAssistant:isAssistantCode(code)});\n        return APP.assistantMap && APP.assistantMap.get(code) || null;\n    }\n    var found=matched();\n    if(found) return found;\n    // Retry both lists for newly added codes. One unavailable source must not block the other.\n    results=await Promise.allSettled([ensureStudentDirectory(true),ensureAssistantDirectory(true)]);\n    found=matched();\n    if(found) return found;\n    var failed=results.find(function(result){return result.status===\"rejected\";});\n    if(failed) throw new Error(\"Ch\u01b0a x\u00e1c minh \u0111\u01b0\u1ee3c m\u00e3 t\u1eeb HocVien / TroGiang. \"+failed.reason.message);\n    return null;\n}\n\n\n/* =========================================================\n   STATUS\n========================================================= */\n\nfunction statusError(student){\n    return student && (student.identitySource===\"HocVien\" || student.identitySource===\"TroGiang\")\n        ?\"\":\"Kh\u00f4ng t\u00ecm th\u1ea5y m\u00e3 trong danh s\u00e1ch HocVien ho\u1eb7c TroGiang.\";\n}\n\n\n/* =========================================================\n   GOI800K PERMISSION\n========================================================= */\n\nasync function loadPermission(gid,column){\n\n    var u=\n        \"https://docs.google.com/spreadsheets/d/\"+\n        APP.SHEET_ID+\n        \"/gviz/tq?gid=\"+\n        gid+\n        \"&headers=0&tqx=out:csv&range=\"+\n        encodeURIComponent(column);\n\n    var rows=csv(\n        await fetchText(u)\n    );\n\n    var o={};\n\n    rows.forEach(r=>\n\n        r.forEach(v=>{\n\n            var c=norm(v);\n\n            if(c){\n                o[c]=true;\n            }\n\n        })\n\n    );\n\n    return o;\n}\n\n\n/* =========================================================\n   LOAD BOTH GOI800K SOURCES\n========================================================= */\n\nasync function loadAccessPermissions(){\n    APP.priorityCodes={};APP.permissionLoaded=false;\n    var results=await Promise.allSettled([\n        loadPermission(APP.PRIORITY_SHEET_GID,\"A:A\"),\n        ensureAssistantDirectory(false)\n    ]);\n    if(results[0].status===\"fulfilled\"){\n        APP.priorityCodes=results[0].value;APP.permissionLoaded=true;\n    }else{console.warn(\"[ThuVien] Ch\u01b0a t\u1ea3i \u0111\u01b0\u1ee3c MaHocVien:\",results[0].reason);}\n    if(results[1].status===\"rejected\") console.warn(\"[ThuVien] Ch\u01b0a t\u1ea3i \u0111\u01b0\u1ee3c TroGiang:\",results[1].reason);\n    syncUpgradeState();return {priorityCodes:APP.priorityCodes,assistantMap:APP.assistantMap};\n}\n\n\nfunction hasLibraryAccess(code){\n    code=norm(code);\n    return Boolean((APP.registryMap && APP.registryMap.has(code)) || isAssistantCode(code));\n}\n\n\nfunction hasPaidAccess(){\n    var code=norm(APP.currentCode);\n    if(!APP.loginCompleted || !code || !hasLibraryAccess(code)) return false;\n    if(isAssistantCode(code)) return true;\n    return Boolean(APP.permissionLoaded && APP.priorityCodes &&\n        Object.prototype.hasOwnProperty.call(APP.priorityCodes,code) && APP.priorityCodes[code]===true);\n}\n\n\nfunction courseKey(value){\n    var text=nt(value).replace(/\\s+/g,\"\");\n    if(/^(all|tatca)$/.test(text)) return \"all\";\n    var match=text.match(/^(?:ocd|d|khoa|k)?0*(\\d+)$/);\n    return match?String(Number(match[1])):text;\n}\n\nfunction matchesStudentCourse(value){\n    var courses=String(value || \"\").split(/[,;|\\/]+/).map(courseKey);\n    // All removes the course restriction; it does not unlock paid videos.\n    if(courses.indexOf(\"all\")>=0) return true;\n    var current=courseKey(APP.student && APP.student.course);\n    return Boolean(current && courses.indexOf(current)>=0);\n}\n\nfunction canWatchVideo(video){\n    if(!video || !APP.loginCompleted || !hasLibraryAccess(APP.currentCode)) return false;\n    if(video.kind===\"replay\" && !matchesStudentCourse(video.course)) return false;\n    return !video.paid || hasPaidAccess();\n}\n\nfunction renderLibraryHeader(){\n    var box=id(\"tpLibraryState\");\n    if(!box) return;\n    box.innerHTML=\"\";\n    [trim(APP.student && APP.student.name) || APP.currentCode,\n     \"Kh\u00f3a \"+(trim(APP.student && APP.student.course) || \"ch\u01b0a c\u1eadp nh\u1eadt\"),\n     hasPaidAccess()?(isAssistantCode(APP.currentCode)?\"Tr\u1ee3 gi\u1ea3ng \"+String.fromCharCode(183)+\" \u0111\u00e3 m\u1edf video tr\u1ea3 ph\u00ed\":\"\u0110\u00e3 m\u1edf video tr\u1ea3 ph\u00ed\"):(APP.permissionLoaded?\"Th\u01b0 vi\u1ec7n c\u01a1 b\u1ea3n\":\"\u0110ang d\u00f9ng th\u01b0 vi\u1ec7n c\u01a1 b\u1ea3n \"+String.fromCharCode(183)+\" ch\u01b0a x\u00e1c minh g\u00f3i n\u00e2ng c\u1ea5p\")]\n    .forEach(function(text){var pill=document.createElement(\"span\");pill.className=\"tp-state-pill\";pill.textContent=text;box.appendChild(pill);});\n}\n\n\n/* =========================================================\n   MANUAL LOGIN\n========================================================= */\n\nasync function login(){\n\n    if(APP.loginCompleted){\n        return;\n    }\n\n    var inp=id(\"tpPasswordInput\");\n    var msg=id(\"tpPasswordMessage\");\n\n    var v=trim(inp.value);\n\n    if(!v){\n\n        msg.textContent=\n            \"Vui l\u00f2ng nh\u1eadp M\u00e3 h\u1ecdc vi\u00ean.\";\n\n        return;\n    }\n\n\n    var code=norm(v);\n    APP.upgradeCode=code;\n\n    msg.textContent=\n        \"\u0110ang x\u00e1c minh M\u00e3 h\u1ecdc vi\u00ean...\";\n\n    try{\n\n        var s=\n            await findStudent(code);\n\n        if(!s){\n            openUpgradePanel();\n            msg.textContent=\n                \"Kh\u00f4ng t\u00ecm th\u1ea5y m\u00e3 trong HocVien ho\u1eb7c TroGiang.\";\n\n            return;\n        }\n\n        var er=statusError(s);\n\n        if(er){\n\n            msg.textContent=er;\n\n            return;\n        }\n\n        APP.student=s;\n        APP.pendingCode=code;\n\n        msg.textContent=\n            \"\u0110ang ki\u1ec3m tra quy\u1ec1n truy c\u1eadp th\u01b0 vi\u1ec7n...\";\n\n        if(hasLibraryAccess(code)){\n            APP.priorityCodes={};\n            APP.permissionLoaded=false;\n            grantAccess();\n            // Enter the free library immediately; only paid playback waits for MaHocVien.\n            await loadAccessPermissions();\n            renderLibraryHeader();\n            renderVideoPage();\n            syncContext();\n        }else{\n\n            APP.pendingCode=\"\";\n\n            msg.textContent=\n                \"M\u00e3 h\u1ecdc vi\u00ean ch\u01b0a c\u00f3 trong HocVien ho\u1eb7c TroGiang.\";\n        }\n\n    }catch(e){\n\n        console.error(\n            \"[ThuVien TV4] Login:\",\n            e\n        );\n\n        msg.textContent=\n            \"Kh\u00f4ng th\u1ec3 k\u1ebft n\u1ed1i d\u1eef li\u1ec7u h\u1ecdc vi\u00ean. Vui l\u00f2ng th\u1eed l\u1ea1i.\";\n    }\n}\n\n\n/* =========================================================\n   MINH H\u1ed2NG VERIFIED CODE\n========================================================= */\n\nfunction getVerifiedMinhHongCode(){\n\n    try{\n\n        var session=\n            window.OCDStudentSession;\n\n        if(\n            !session ||\n            typeof session.getState!==\"function\"\n        ){\n            return \"\";\n        }\n\n        var state=session.getState();\n\n        if(\n            !state ||\n            state.verified!==true\n        ){\n            return \"\";\n        }\n\n        return norm(state.code);\n\n    }catch(e){\n\n        return \"\";\n    }\n}\n\n\n/* =========================================================\n   AUTO LOGIN FROM MINH H\u1ed2NG\n========================================================= */\n\nasync function tryAutoLoginFromMinhHong(){\n\n    if(\n        APP.loginCompleted ||\n        APP.autoLoginRunning\n    ){\n        return false;\n    }\n\n    var code=\n        getVerifiedMinhHongCode();\n\n    if(!code){\n        return false;\n    }\n\n    if(\n        APP.autoLoginFinished &&\n        APP.autoLoginCode===code\n    ){\n        return false;\n    }\n\n    APP.autoLoginRunning=true;\n    APP.autoLoginCode=code;\n    APP.upgradeCode=code;\n\n    var msg=id(\"tpPasswordMessage\");\n    var inp=id(\"tpPasswordInput\");\n    var button=id(\"tpLoginButton\");\n\n    try{\n\n        if(inp){\n            inp.value=code;\n        }\n\n        if(button){\n            button.disabled=true;\n        }\n\n        if(msg){\n            msg.textContent=\n                \"\u0110\u00e3 nh\u1eadn di\u1ec7n h\u1ecdc vi\u00ean. \u0110ang ki\u1ec3m tra quy\u1ec1n th\u01b0 vi\u1ec7n...\";\n        }\n\n        var student=\n            await findStudent(code);\n\n        if(!student){\n            openUpgradePanel();\n            if(msg){\n                msg.textContent=\"\";\n            }\n\n            if(inp){\n                inp.value=\"\";\n            }\n\n            APP.autoLoginFinished=true;\n\n            return false;\n        }\n\n\n        var er=statusError(student);\n\n        if(er){\n\n            if(msg){\n                msg.textContent=er;\n            }\n\n            APP.autoLoginFinished=true;\n\n            return false;\n        }\n\n\n        if(!hasLibraryAccess(code)){\n\n            APP.autoLoginFinished=true;\n\n            if(msg){\n\n                msg.textContent=\n                    \"M\u00e3 h\u1ecdc vi\u00ean \u0111\u00e3 \u0111\u01b0\u1ee3c nh\u1eadn di\u1ec7n nh\u01b0ng ch\u01b0a c\u00f3 trong HocVien ho\u1eb7c TroGiang.\";\n            }\n\n            return false;\n        }\n\n\n        APP.student=student;\n        APP.pendingCode=code;\n        APP.priorityCodes={};\n        APP.permissionLoaded=false;\n        grantAccess();\n        APP.autoLoginFinished=true;\n        await loadAccessPermissions();\n        renderLibraryHeader();\n        renderVideoPage();\n        syncContext();\n\n        return true;\n\n    }catch(e){\n\n        console.error(\n            \"[ThuVien TV4] Auto Login:\",\n            e\n        );\n\n        if(msg){\n            msg.textContent=\"\";\n        }\n\n        return false;\n\n    }finally{\n\n        APP.autoLoginRunning=false;\n\n        if(button){\n            button.disabled=false;\n        }\n    }\n}\n\n\n/* =========================================================\n   LOGIN HELPERS\n========================================================= */\n\nfunction passwordKey(e){\n\n    if(\n        e.key===\"Enter\" ||\n        e.keyCode===13\n    ){\n\n        e.preventDefault();\n\n        login();\n    }\n}\n\n\nfunction openLibrary(){\n\n    id(\"tpLoginScreen\").style.display=\"none\";\n    id(\"tpLibraryContent\").style.display=\"block\";\n    renderReferenceAccess();\n}\n\n\nfunction grantAccess(){\n\n    APP.loginMode=\"student\";\n\n    APP.currentCode=\n        APP.pendingCode;\n\n    APP.pendingCode=\"\";\n\n    APP.loginCompleted=true;\n\n    id(\"tpPasswordMessage\").textContent=\"\";\n\n    openLibrary();\n\n    prepareWelcome();\n\n    connectMinhHong();\n\n    loadVideos();\n\n    loadProfile(false);\n}\n\n\nfunction connectMinhHong(){\n\n    var s=window.OCDStudentSession;\n\n    if(\n        s &&\n        typeof s.confirmStudent===\"function\"\n    ){\n\n        try{\n\n            s.confirmStudent(\n                APP.currentCode,\n                \"thu-vien\"\n            );\n\n        }catch(e){}\n    }\n\n    syncContext();\n}\n\n\n/* =========================================================\n   LEVEL\n========================================================= */\n\nfunction levelName(p){\n\n    var out=LEVELS[0].name;\n\n    LEVELS.forEach(x=>{\n\n        if(p>=x.min){\n            out=x.name;\n        }\n\n    });\n\n    return out;\n}\n\n\n/* =========================================================\n   SUBMISSION HELPERS\n========================================================= */\n\nfunction driveId(u){\n\n    var m=\n        String(u||\"\").match(\n            /\\/file\\/d\\/([^/?&#]+)|\\/d\\/([^/?&#]+)|[?&]id=([^&#]+)/i\n        );\n\n    return m\n        ?(m[1]||m[2]||m[3])\n        :\"\";\n}\n\n\nfunction compact(v){\n\n    var m=\n        String(v||\"\").match(\n            /^(\\d{1,2})[\\/-](\\d{1,2})[\\/-](\\d{4})[\\s,]+(\\d{1,2}):(\\d{2})(?::(\\d{2}))?/\n        );\n\n    if(!m){\n        return \"\";\n    }\n\n    var p=\n        n=>String(n).padStart(2,\"0\");\n\n    return(\n        m[3]+\n        p(m[2])+\n        p(m[1])+\n        p(m[4])+\n        p(m[5])+\n        p(m[6]||0)\n    );\n}\n\n\nfunction submissionId(ts,c,f){\n\n    return(\n        compact(ts)+\n        \"|\"+\n        trim(c)+\n        \"|\"+\n        (driveId(f)||trim(f))\n    );\n}\n\n\nfunction deletedSet(R,text){\n\n    var rows=\n        R.parseCSV(text||\"\");\n\n    var set=new Set;\n\n    if(rows.length<2){\n        return set;\n    }\n\n    var h=rows[0];\n\n    var ic=\n        R.findColumn(\n            h,\n            [\n                \"m\u00e3 b\u00e0i n\u1ed9p\",\n                \"ma bai nop\",\n                \"submission id\"\n            ]\n        );\n\n    var ac=\n        R.findColumn(\n            h,\n            [\n                \"h\u00e0nh \u0111\u1ed9ng\",\n                \"hanh dong\",\n                \"action\"\n            ]\n        );\n\n    var state=new Map;\n\n    rows.slice(1).forEach(r=>{\n\n        var x=trim(r[ic]);\n\n        if(!x){\n            return;\n        }\n\n        var a=\n            ac>=0\n            ?nt(r[ac])\n            :\"xoa\";\n\n        state.set(\n            x,\n            !(\n                a.includes(\"khoi phuc\") ||\n                a===\"restore\"\n            )\n        );\n    });\n\n    state.forEach((v,k)=>{\n\n        if(v){\n            set.add(k);\n        }\n\n    });\n\n    return set;\n}\n\n\nfunction validSubmissionCsv(R,text,deleted){\n\n    var rows=\n        R.parseCSV(text||\"\");\n\n    if(!rows.length){\n        return \"\";\n    }\n\n    var h=rows[0];\n\n    var cc=\n        R.findColumn(\n            h,\n            [\n                \"m\u00e3 h\u1ecdc vi\u00ean\",\n                \"ma hoc vien\"\n            ]\n        );\n\n    var tc=\n        R.findColumn(\n            h,\n            [\n                \"d\u1ea5u th\u1eddi gian\",\n                \"timestamp\"\n            ]\n        );\n\n    var fc=\n        R.findColumn(\n            h,\n            [\n                \"t\u1ea3i b\u00e0i t\u1eadp l\u00ean\",\n                \"tai bai tap len\",\n                \"b\u00e0i t\u1eadp\"\n            ]\n        );\n\n    var ic=\n        R.findColumn(\n            h,\n            [\n                \"m\u00e3 b\u00e0i n\u1ed9p\",\n                \"submission id\"\n            ]\n        );\n\n    if(cc<0){\n        return rowsToCsv([h]);\n    }\n\n    var keep=[h];\n\n    rows.slice(1).forEach(r=>{\n\n        if(\n            R.normalizeCode(r[cc]) !==\n            R.normalizeCode(APP.currentCode)\n        ){\n            return;\n        }\n\n        var sid=\n            ic>=0\n            ?trim(r[ic])\n            :\"\";\n\n        if(!sid){\n\n            sid=\n                submissionId(\n                    tc>=0?r[tc]:\"\",\n                    r[cc],\n                    fc>=0?r[fc]:\"\"\n                );\n        }\n\n        if(!deleted.has(sid)){\n            keep.push(r);\n        }\n    });\n\n    return rowsToCsv(keep);\n}\n\n\nfunction rowsToCsv(rows){\n\n    return rows.map(r=>\n\n        r.map(v=>{\n\n            v=String(\n                v==null?\"\":v\n            );\n\n            return /[\",\\r\\n]/.test(v)\n                ?'\"'+v.replace(/\"/g,'\"\"')+'\"'\n                :v;\n\n        }).join(\",\")\n\n    ).join(\"\\r\\n\");\n}\n\n\nfunction rankFromCsv(R,text){\n\n    var rows=\n        R.parseCSV(text||\"\");\n\n    if(rows.length<2){\n        return 0;\n    }\n\n    var sc=\n        R.findColumn(\n            rows[0],\n            [\n                \"\u0111i\u1ec3m\",\n                \"diem\",\n                \"\u0111i\u1ec3m s\u1ed1\",\n                \"diem so\",\n                \"\u0111i\u1ec3m gi\u00e1o vi\u00ean\"\n            ]\n        );\n\n    var total=0;\n    var count=rows.length-1;\n\n    if(sc>=0){\n\n        rows.slice(1).forEach(r=>{\n\n            var x=\n                typeof R.parseScore===\"function\"\n                ?R.parseScore(r[sc])\n                :parseFloat(\n                    String(r[sc]).replace(\",\",\".\")\n                );\n\n            if(\n                x!==null &&\n                !isNaN(x)\n            ){\n                total+=x;\n            }\n\n        });\n    }\n\n    return count+total;\n}\n\n\n/* =========================================================\n   TV4 - AVATAR RESOLVER\n\n   \u01afu ti\u00ean:\n   1. Core helper n\u1ebfu c\u00f3\n   2. canonical.avatar\n   3. canonical.avatarImage\n   4. canonical.profileAvatar\n========================================================= */\n\nfunction resolveCanonicalAvatar(R,canonical,ownedItems){\n\n    var avatar=\"\";\n\n\n    if(\n        R &&\n        typeof R.getProfileAvatar===\"function\"\n    ){\n\n        try{\n\n            var a=\n                R.getProfileAvatar(\n                    ownedItems\n                );\n\n            if(typeof a===\"string\"){\n\n                avatar=trim(a);\n\n            }else if(\n                a &&\n                typeof a===\"object\"\n            ){\n\n                avatar=\n                    trim(\n                        a.image ||\n                        a.url ||\n                        a.avatar ||\n                        (\n                            a.gift &&\n                            a.gift.image\n                        )\n                    );\n            }\n\n        }catch(e){}\n    }\n\n\n    if(\n        !avatar &&\n        canonical\n    ){\n\n        if(\n            typeof canonical.avatar===\"string\"\n        ){\n\n            avatar=\n                trim(canonical.avatar);\n\n        }else if(\n            canonical.avatar &&\n            typeof canonical.avatar===\"object\"\n        ){\n\n            avatar=\n                trim(\n                    canonical.avatar.image ||\n                    canonical.avatar.url ||\n                    canonical.avatar.avatar\n                );\n        }\n    }\n\n\n    if(\n        !avatar &&\n        canonical\n    ){\n\n        avatar=\n            trim(\n                canonical.avatarImage ||\n                canonical.profileAvatar ||\n                canonical.profileImage\n            );\n    }\n\n\n    return avatar;\n}\n\n\n/* =========================================================\n   LOAD PROFILE\n========================================================= */\n\nasync function loadProfile(force){\n\n    if(APP.profileRefreshing){\n        return;\n    }\n\n    APP.profileRefreshing=true;\n\n    try{\n\n        var R=\n            await waitCore();\n\n        var subUrl=\n            R.CONFIG &&\n            R.CONFIG.studentCsv\n            ?R.CONFIG.studentCsv\n            :APP.SUBMISSIONS;\n\n        var res=\n            await Promise.all([\n\n                R.fetchCSV(subUrl),\n\n                R.fetchCSV(\n                    APP.DELETE_LOG\n                )\n\n            ]);\n\n        var filtered=\n            validSubmissionCsv(\n                R,\n                res[0],\n                deletedSet(\n                    R,\n                    res[1]\n                )\n            );\n\n        APP.validSubmissionCsv=\n            filtered;\n\n        var rank=\n            rankFromCsv(\n                R,\n                filtered\n            );\n\n        // Older Core versions do not forward force to the shared inventory.\n        if(typeof R.loadSharedRewardData===\"function\"){\n            await R.loadSharedRewardData(Boolean(force));\n        }\n\n        var canonical=\n            await R.getStudentRewardProfile(\n                R.normalizeCode(\n                    APP.currentCode\n                ),\n                filtered,\n                Boolean(force),\n                {adminBypass:true}\n            );\n\n\n        var gems=\n            canonical &&\n            canonical.gems &&\n            typeof canonical.gems===\"object\"\n            ?canonical.gems\n            :(\n                canonical &&\n                canonical.rewardData &&\n                canonical.rewardData.gems\n            )||{};\n\n\n        var ownedItems=\n            canonical &&\n            Array.isArray(\n                canonical.ownedItems\n            )\n            ?canonical.ownedItems\n            :[];\n\n\n        var avatar=\n            resolveCanonicalAvatar(\n                R,\n                canonical,\n                ownedItems\n            );\n\n\n        var reward=resolveAchievementReward(R,canonical,filtered);\n\n\n        var total=0;\n\n        (\n            R.GEM_ORDER ||\n            Object.keys(gems)\n        ).forEach(k=>{\n\n            total+=\n                Number(\n                    gems[k]||0\n                );\n        });\n\n\n        APP.profile={\n\n            name:\n            trim(\n                canonical &&\n                canonical.name\n            )\n            ||\n            trim(\n                APP.student &&\n                APP.student.name\n            )\n            ||\n            (\n                \"H\u1ecdc vi\u00ean \"+\n                APP.currentCode\n            ),\n\n            avatar:avatar,\n\n            points:rank,\n\n            title:\n            levelName(rank),\n\n            gems:gems,\n\n            totalGems:total,\n\n            ownedItems:ownedItems,\n\n            reward:reward,\n\n            canonical:canonical,\n\n            RS:R\n        };\n\n\n        renderWelcome();\n\n        renderVideoPage();\n\n        syncContext();\n\n\n    }catch(e){\n\n        console.error(\n            \"[ThuVien TV4]\",\n            e\n        );\n\n        APP.profile={\n\n            name:\n            trim(\n                APP.student &&\n                APP.student.name\n            )\n            ||\n            APP.currentCode,\n\n            avatar:\"\",\n\n            points:0,\n\n            title:\"Ch\u01b0a \u0111\u1ed3ng b\u1ed9\",\n\n            gems:null,\n\n            totalGems:0,\n\n            ownedItems:[],\n\n            reward:null,\n\n            RS:null\n        };\n\n        renderWelcome();\n\n        syncContext();\n\n    }finally{\n\n        APP.profileRefreshing=false;\n    }\n}\n\n\n/* =========================================================\n   PREPARE WELCOME\n========================================================= */\n\nfunction prepareWelcome(){\n    id(\"tpProfilePanel\").style.display=\"block\";\n    id(\"tpProfilePanel\").open=false;\n    renderLibraryHeader();\n\n    id(\n        \"tpStudentWelcome\"\n    ).style.display=\"block\";\n\n    id(\n        \"tpWelcomeName\"\n    ).textContent=\n        trim(\n            APP.student &&\n            APP.student.name\n        )\n        ||\n        \"\u0110ang \u0111\u1ed3ng b\u1ed9 h\u1ed3 s\u01a1...\";\n\n    id(\n        \"tpWelcomeCode\"\n    ).textContent=\n        \"M\u00e3 h\u1ecdc vi\u00ean: \"+\n        APP.currentCode;\n}\n\n\n/* =========================================================\n   TV4 - RENDER AVATAR\n========================================================= */\n\nfunction ownedItemQuantity(item){\n    if(!item) return 0;\n    var raw=item.quantity;\n    if(raw===undefined || raw===null || raw===\"\") raw=1;\n    var value=Number(raw);\n    return isFinite(value) && value>0 ? value : 0;\n}\n\nfunction currentProfileItems(p){\n    return (p && Array.isArray(p.ownedItems) ? p.ownedItems : [])\n        .filter(function(item){return ownedItemQuantity(item)>0;});\n}\n\nfunction renderStudentAvatar(){\n    var box=id(\"tpStudentAvatar\");\n    if(!box) return;\n    box.innerHTML=\"\";\n    var p=APP.profile;\n    var R=p && p.RS;\n    var items=currentProfileItems(p);\n    var avatar=resolveCanonicalAvatar(R,p && p.canonical,items);\n    var face=document.createElement(\"span\");\n    face.className=\"tp-avatar-face\";\n    face.textContent=\"\u66f8\";\n    box.appendChild(face);\n    if(avatar){\n        var img=document.createElement(\"img\");\n        img.alt=p.name || \"Avatar h\u1ecdc vi\u00ean\";\n        img.decoding=\"async\";\n        img.src=R && typeof R.convertDriveImageUrl===\"function\"\n            ?R.convertDriveImageUrl(avatar,160):avatar;\n        img.onerror=function(){face.textContent=\"\u66f8\";};\n        face.textContent=\"\";\n        face.appendChild(img);\n    }\n    var frame=R && typeof R.getProfileAvatarFrame===\"function\"\n        ?R.getProfileAvatarFrame(items):\"\";\n    if(frame){\n        var overlay=document.createElement(\"img\");\n        overlay.className=\"tp-avatar-frame\";\n        overlay.alt=\"\";\n        overlay.setAttribute(\"aria-hidden\",\"true\");\n        overlay.decoding=\"async\";\n        overlay.src=frame;\n        overlay.onerror=function(){overlay.remove();};\n        box.appendChild(overlay);\n    }\n}\n\nfunction renderStudentEffects(){\n    var p=APP.profile;\n    var R=p && p.RS;\n    var items=currentProfileItems(p);\n    var card=id(\"tpStudentWelcome\");\n    var background=R && typeof R.getProfileBackground===\"function\"\n        ?R.getProfileBackground(items):\"\";\n    if(card){\n        card.classList.toggle(\"tp-has-background\",Boolean(background));\n        card.style.backgroundImage=background ? \"url(\"+JSON.stringify(background)+\")\":\"\";\n    }\n    var name=id(\"tpWelcomeName\");\n    if(!name) return;\n    var wrap=id(\"tpWelcomeNameEffect\");\n    if(!wrap){\n        wrap=document.createElement(\"div\");\n        wrap.id=\"tpWelcomeNameEffect\";\n        wrap.className=\"tp-name-effect\";\n        name.parentNode.insertBefore(wrap,name);\n        wrap.appendChild(name);\n    }\n    wrap.classList.remove(\"reward-multitask-wrap\",\"reward-multitask-size-medium\");\n    name.classList.remove(\"reward-multitask-name\");\n    wrap.querySelectorAll(\".reward-multitask-star\").forEach(function(star){star.remove();});\n    var enabled=R && typeof R.hasMultitaskPotion===\"function\" && R.hasMultitaskPotion(items);\n    if(enabled && typeof R.applyMultitaskEffect===\"function\"){\n        R.applyMultitaskEffect(wrap,name,{size:\"medium\"});\n    }\n}\n\n\n/* =========================================================\n   RENDER WELCOME\n========================================================= */\n\nfunction renderWelcome(){\n\n    var p=APP.profile;\n\n    if(!p){\n        return;\n    }\n\n    id(\n        \"tpWelcomeName\"\n    ).textContent=\n        p.name;\n\n    id(\n        \"tpWelcomePoints\"\n    ).textContent=\n        Number(\n            p.points||0\n        ).toLocaleString(\n            \"vi-VN\"\n        );\n\n    id(\n        \"tpWelcomeGemTotal\"\n    ).textContent=\n        p.gems\n        ?Number(\n            p.totalGems||0\n        ).toLocaleString(\n            \"vi-VN\"\n        )\n        :\"\u2014\";\n\n    id(\n        \"tpWelcomeTitle\"\n    ).textContent=\n        p.title||\"\u2014\";\n\n\n    renderStudentAvatar();\n    renderStudentEffects();\n    renderLibraryHeader();\n\n    renderGems();\n\n    renderItems();\n\n    renderGifts();\n}\n\n\n/* =========================================================\n   GEMS\n========================================================= */\n\nfunction renderGems(){\n\n    var b=id(\"tpHeaderGems\");\n\n    b.innerHTML=\"\";\n\n    var p=APP.profile;\n    var R=p&&p.RS;\n\n    if(\n        !p ||\n        !p.gems ||\n        !R\n    ){\n\n        b.innerHTML=\n            '<span class=\"tp-no-gem\">Ch\u01b0a c\u00f3 linh th\u1ea1ch</span>';\n\n        return;\n    }\n\n    var any=false;\n\n    (\n        R.GEM_ORDER ||\n        Object.keys(p.gems)\n    ).forEach(k=>{\n\n        var n=\n            Number(\n                p.gems[k]||0\n            );\n\n        var g=\n            R.GEM_TYPES &&\n            R.GEM_TYPES[k];\n\n        if(\n            n<=0 ||\n            !g\n        ){\n            return;\n        }\n\n        any=true;\n\n        var s=\n            document.createElement(\n                \"span\"\n            );\n\n        s.className=\n            \"tp-head-gem\";\n\n        var im=\n            document.createElement(\n                \"img\"\n            );\n\n        im.src=\n            typeof R.convertDriveImageUrl===\"function\"\n            ?R.convertDriveImageUrl(\n                g.image,\n                48\n            )\n            :g.image;\n\n        im.alt=\n            g.displayName||k;\n\n        im.onerror=function(){\n            this.style.display=\"none\";\n        };\n\n        var st=\n            document.createElement(\n                \"strong\"\n            );\n\n        st.textContent=n;\n\n        s.append(\n            im,\n            st\n        );\n\n        b.appendChild(s);\n    });\n\n\n    if(!any){\n\n        b.innerHTML=\n            '<span class=\"tp-no-gem\">Ch\u01b0a c\u00f3 linh th\u1ea1ch</span>';\n    }\n}\n\n\n/* =========================================================\n   TV4 - GROUP OWNED ITEMS\n========================================================= */\n\nfunction groupOwnedItemsForDisplay(items){\n\n    var map=new Map();\n\n    (\n        Array.isArray(items)\n        ?items\n        :[]\n    ).forEach(function(item){\n\n        if(!item){\n            return;\n        }\n\n\n        var name=\n            cleanItemDisplayName(\n                item.giftName ||\n                item.name ||\n                (\n                    item.gift &&\n                    item.gift.name\n                )\n            );\n\n\n        if(!name){\n            return;\n        }\n\n\n        var key=nt(name);\n\n        if(!key){\n            return;\n        }\n\n\n        var quantity=ownedItemQuantity(item);\n\n        if(\n            !isFinite(quantity) ||\n            quantity<=0\n        ){\n            return;\n        }\n\n\n        var image=\n            trim(\n                item.image ||\n                (\n                    item.gift &&\n                    item.gift.image\n                )\n            );\n\n\n        if(!map.has(key)){\n\n            map.set(\n                key,\n                {\n                    name:name,\n                    quantity:0,\n                    image:image\n                }\n            );\n        }\n\n\n        var current=\n            map.get(key);\n\n        current.quantity+=quantity;\n\n\n        if(\n            !current.image &&\n            image\n        ){\n            current.image=image;\n        }\n\n    });\n\n\n    return Array.from(\n        map.values()\n    );\n}\n\n\n/* =========================================================\n   TV4 - RENDER ITEMS\n========================================================= */\n\nfunction renderItems(){\n\n    var b=\n        id(\"tpHeaderItems\");\n\n    if(!b){\n        return;\n    }\n\n    b.innerHTML=\"\";\n\n\n    var p=APP.profile;\n    var R=p&&p.RS;\n\n\n    var items=\n        groupOwnedItemsForDisplay(\n            p&&p.ownedItems\n        );\n\n\n    if(!items.length){\n\n        b.innerHTML=\n            '<span class=\"tp-no-item\">Ch\u01b0a c\u00f3 v\u1eadt ph\u1ea9m</span>';\n\n        return;\n    }\n\n\n    items.forEach(function(item){\n\n        var card=\n            document.createElement(\n                \"div\"\n            );\n\n        card.className=\n            \"tp-head-item\";\n\n\n        /*\n        TV4:\n        Kh\u00f4ng d\u00f9ng entity HTML.\n        */\n\n        card.title=\n            item.name+\n            \" \"+\n            String.fromCharCode(215)+\n            item.quantity;\n\n\n        var imageBox=\n            document.createElement(\n                \"div\"\n            );\n\n        imageBox.className=\n            \"tp-head-item-image\";\n\n\n        if(item.image){\n\n            var img=\n                document.createElement(\n                    \"img\"\n                );\n\n            img.alt=item.name;\n\n            img.loading=\"lazy\";\n\n            img.decoding=\"async\";\n\n\n            img.src=\n                R &&\n                typeof R.convertDriveImageUrl===\"function\"\n                ?R.convertDriveImageUrl(\n                    item.image,\n                    96\n                )\n                :item.image;\n\n\n            img.onerror=function(){\n\n                imageBox.innerHTML=\"\";\n                imageBox.textContent=\"\u7269\";\n            };\n\n\n            imageBox.appendChild(img);\n\n        }else{\n\n            imageBox.textContent=\"\u7269\";\n        }\n\n\n        var info=\n            document.createElement(\n                \"div\"\n            );\n\n        info.className=\n            \"tp-head-item-info\";\n\n\n        var name=\n            document.createElement(\n                \"span\"\n            );\n\n        name.className=\n            \"tp-head-item-name\";\n\n        name.textContent=\n            item.name;\n\n\n        var qty=\n            document.createElement(\n                \"strong\"\n            );\n\n        qty.className=\n            \"tp-head-item-qty\";\n\n\n        /*\n        TV4 FIX:\n        Kh\u00f4ng ghi:\n        &#215;\n\n        Kh\u00f4ng d\u00f9ng innerHTML.\n\n        T\u1ea1o tr\u1ef1c ti\u1ebfp Unicode \u00d7.\n        */\n\n        qty.textContent=\n            String.fromCharCode(215)+\n            Number(\n                item.quantity||1\n            ).toLocaleString(\n                \"vi-VN\"\n            );\n\n\n        info.append(\n            name,\n            qty\n        );\n\n\n        card.append(\n            imageBox,\n            info\n        );\n\n\n        b.appendChild(card);\n\n    });\n}\n\n\n/* =========================================================\n   GIFTS\n========================================================= */\n\n// Match BXH: rewardData first, then Core calculation from undeleted submissions.\nfunction resolveAchievementReward(R,canonical,submissionCsv){\n    var root=canonical && canonical.profile || canonical || {};\n    var source=root.rewardData || root.reward || {};\n    var computed={longestStreak:0,bestHighRun:0,streakGift:null,highScoreGift:null};\n    if(R && typeof R.calculateStudentRewardData===\"function\"){\n        var rows=R.parseCSV(submissionCsv || \"\");\n        if(rows.length){\n            var headers=rows[0];\n            var code=R.findColumn(headers,[\"m\u00e3 h\u1ecdc vi\u00ean\",\"ma hoc vien\"]);\n            var time=R.findColumn(headers,[\"d\u1ea5u th\u1eddi gian\",\"dau thoi gian\",\"timestamp\"]);\n            var score=R.findColumn(headers,[\"\u0111i\u1ec3m\",\"diem\",\"\u0111i\u1ec3m s\u1ed1\",\"diem so\"]);\n            var target=R.normalizeCode(APP.currentCode);\n            var submissions=rows.slice(1).map(function(row,index){\n                return {\n                    code:code>=0?R.normalizeCode(row[code]):\"\",\n                    timestamp:time>=0?row[time] || \"\":\"\",\n                    score:score>=0?row[score] || \"\":\"\",\n                    originalIndex:index+1\n                };\n            }).filter(function(item){return item.code===target;});\n            computed=R.calculateStudentRewardData(submissions);\n        }\n    }\n    var reward=Object.assign({},computed);\n    Object.keys(source).forEach(function(key){\n        if(source[key]!==undefined) reward[key]=source[key];\n    });\n    [\"streakGift\",\"highScoreGift\"].forEach(function(key){\n        var achieved=reward[key];\n        var fallback=computed[key];\n        if(achieved && !achieved.icon && fallback && achieved.name===fallback.name){\n            reward[key]=Object.assign({},fallback,achieved,{icon:fallback.icon});\n        }\n    });\n    return reward;\n}\n\nfunction renderGifts(){\n    var b=id(\"tpGiftGrid\");\n    if(!b) return;\n    b.innerHTML=\"\";\n    var r=APP.profile && APP.profile.reward || {};\n    b.appendChild(gift(\n        r.streakGift,\n        \"Qu\u00e0 luy\u1ec7n t\u1eadp li\u00ean t\u1ee5c\",\n        \"Chu\u1ed7i luy\u1ec7n t\u1eadp d\u00e0i nh\u1ea5t: \"+Number(r.longestStreak || 0)+\" ng\u00e0y.\"\n    ));\n    b.appendChild(gift(\n        r.highScoreGift,\n        \"Qu\u00e0 chu\u1ed7i \u0111i\u1ec3m cao\",\n        \"Chu\u1ed7i \u0111i\u1ec3m cao d\u00e0i nh\u1ea5t: \"+Number(r.bestHighRun || 0)+\" b\u00e0i.\"\n    ));\n}\n\nfunction achievementIconText(value){\n    // Accept Unicode and legacy numeric entities without inserting HTML.\n    return String(value || String.fromCodePoint(0x1F381))\n        .replace(/&#(x[0-9a-f]+|[0-9]+);/gi,function(entity,code){\n            var number=code.charAt(0).toLowerCase()===\"x\"\n                ?parseInt(code.slice(1),16):parseInt(code,10);\n            return number>=0 && number<=0x10FFFF?String.fromCodePoint(number):entity;\n        });\n}\n\nfunction gift(g,t,d){\n    var c=document.createElement(\"div\");\n    c.className=\"tp-gift\";\n    var i=document.createElement(\"div\");\n    i.className=\"tp-gift-icon\";\n    i.textContent=g?achievementIconText(g.icon):String.fromCodePoint(0x1F381);\n    i.setAttribute(\"aria-hidden\",\"true\");\n    var x=document.createElement(\"div\");\n    var title=document.createElement(\"strong\");\n    var description=document.createElement(\"p\");\n    title.textContent=g && g.name?g.name:t;\n    description.textContent=d+(g?\"\":\" Ch\u01b0a \u0111\u1ea1t th\u00e0nh t\u00edch.\");\n    c.title=title.textContent+\" \u2014 \"+description.textContent;\n    x.append(title,description);\n    c.append(i,x);\n    return c;\n}\n\n\n/* =========================================================\n   VIDEOS\n========================================================= */\n\nasync function loadVideos(){\n    try{\n        var url=\"https://docs.google.com/spreadsheets/d/\"+APP.SHEET_ID+\n            \"/gviz/tq?gid=\"+APP.SHEET_GID+\"&headers=1&tqx=out:csv&range=A:G\";\n        var groups=partitionLibraryVideos(csv(await fetchText(url)));\n        APP.videos=groups.guides;\n        APP.replays=groups.replays;\n        APP.page=1;\n        APP.replayPage=1;\n        renderVideoPage();\n        syncContext();\n    }catch(error){\n        console.error(\"[ThuVien] Video:\",error);\n        [\"tpVideoGrid\",\"tpReplayGrid\"].forEach(function(key){id(key).innerHTML='<div class=\"tp-status\">Kh\u00f4ng th\u1ec3 t\u1ea3i d\u1eef li\u1ec7u video. Vui l\u00f2ng t\u1ea3i l\u1ea1i trang.</div>';});\n    }\n}\n\nfunction partitionLibraryVideos(rows){\n    var result={guides:[],replays:[]};\n    (rows || []).slice(1).forEach(function(row,index){\n        var youtube=youtubeId(row[2]);\n        if(!trim(row[1]) || !youtube) return;\n        var replay=nt(row[6])===\"video xem lai\";\n        var section=nt(row[6]);\n        if(section && !replay && section!==\"video huong dan\") return;\n        var course=trim(row[5]);\n        if(replay && !matchesStudentCourse(course)) return;\n        if(!replay && course && !matchesStudentCourse(course)) return;\n        var ordinal=Number(row[0]);\n        var video={lesson:trim(row[0]) || index+1,title:trim(row[1]),id:youtube,\n            description:trim(row[3]),paid:nt(row[4])===\"tra phi\",course:course,\n            kind:replay?\"replay\":\"guide\",difficulty:replay?0:(ordinal>0?ordinal:index+1)*APP.DIFFICULTY_STEP};\n        (replay?result.replays:result.guides).push(video);\n    });\n    return result;\n}\n\n\nfunction youtubeId(v){\n\n    v=\n        trim(v)\n        .replace(\n            /&amp;/g,\n            \"&\"\n        );\n\n    var m=\n        v.match(\n            /(?:youtu\\.be\\/|[?&]v=|\\/(?:shorts|embed|live)\\/)([A-Za-z0-9_-]{11})/\n        );\n\n    return /^[A-Za-z0-9_-]{11}$/.test(v)\n        ?v\n        :(m?m[1]:\"\");\n}\n\n\nfunction studentPoints(){\n\n    if(\n        APP.loginMode!==\"student\"\n    ){\n        return null;\n    }\n\n    if(!APP.profile){\n        return null;\n    }\n\n    return Number(\n        APP.profile.points||0\n    );\n}\n\n\nfunction renderReferenceAccess(){\n    var book=id(\"tpPaidReferenceBook\");\n    if(!book) return;\n    var allowed=hasPaidAccess();\n    book.hidden=!allowed;\n    book.style.display=allowed?\"\":\"none\";\n    if(allowed){\n        book.href=\"https://drive.google.com/file/d/1fnc2DUZewco11OoNc89hm4x1-jAT90Lu/view?usp=sharing\";\n    }else{\n        book.removeAttribute(\"href\");\n    }\n}\n\nfunction renderVideoPage(){\n    renderReferenceAccess();\n    renderVideoList(\"guide\");\n    renderVideoList(\"replay\");\n}\n\nfunction renderVideoList(kind){\n    var replay=kind===\"replay\";\n    var grid=id(replay?\"tpReplayGrid\":\"tpVideoGrid\");\n    var videos=replay?APP.replays:APP.videos;\n    var pageKey=replay?\"replayPage\":\"page\";\n    if(!grid) return;\n    grid.innerHTML=\"\";\n    if(replay){\n        id(\"tpReplayNote\").textContent=\"B\u00e0i gi\u1ea3ng c\u1ee7a kh\u00f3a \"+(trim(APP.student && APP.student.course) || \"ch\u01b0a c\u1eadp nh\u1eadt\")+\" \u0111ang theo h\u1ecdc.\";\n    }\n    APP[pageKey]=Math.max(1,Math.min(APP[pageKey],Math.ceil(videos.length/APP.PAGE_SIZE) || 1));\n    if(!videos.length){\n        grid.innerHTML='<div class=\"tp-status\">'+(replay?\"Ch\u01b0a c\u00f3 video xem l\u1ea1i cho kh\u00f3a \u0111ang theo h\u1ecdc.\":\"Ch\u01b0a c\u00f3 video h\u01b0\u1edbng d\u1eabn.\")+'</div>';\n    }else{\n        var start=(APP[pageKey]-1)*APP.PAGE_SIZE;\n        videos.slice(start,start+APP.PAGE_SIZE).forEach(function(video){grid.appendChild(videoCard(video));});\n    }\n    renderPages(kind);\n}\n\n\nfunction lockedPaidVideoCard(video){\n    var card=document.createElement(\"article\");\n    card.className=\"tp-video locked tp-upgrade-video\";\n    var body=document.createElement(\"div\");body.className=\"tp-upgrade-video-body\";\n    var icon=document.createElement(\"div\");icon.className=\"tp-upgrade-video-icon\";\n    icon.textContent=String.fromCodePoint(0x1F512);\n    icon.setAttribute(\"aria-hidden\",\"true\");\n    var label=document.createElement(\"span\");label.className=\"tp-lesson\";\n    label.textContent=(video.kind===\"replay\"?\"VIDEO XEM L\u1ea0I\":\"VIDEO H\u01af\u1edaNG D\u1eaaN\")+\n        \" \"+String.fromCharCode(183)+\" TR\u1ea2 PH\u00cd\";\n    var title=document.createElement(\"h3\");\n    title.textContent=\"N\u00e2ng c\u1ea5p g\u00f3i h\u1ecdc vi\u00ean \u0111\u1ec3 xem Video tr\u1ea3 ph\u00ed\";\n    var note=document.createElement(\"p\");\n    note.textContent=\"M\u00e3 h\u1ecdc vi\u00ean c\u1ee7a b\u1ea1n ch\u01b0a \u0111\u01b0\u1ee3c m\u1edf quy\u1ec1n xem video n\u00e0y.\";\n    body.append(icon,label,title,note,upgradePaymentCard());card.appendChild(body);\n    return card;\n}\n\nfunction videoCard(video){\n    if(video.paid && !hasPaidAccess()) return lockedPaidVideoCard(video);\n    var points=studentPoints();\n    var allowed=canWatchVideo(video);\n    var card=document.createElement(\"article\");\n    card.className=\"tp-video\"+(!allowed?\" locked\":(points!==null && points<video.difficulty?\" low\":\"\"));\n    var thumb=document.createElement(\"div\");\n    thumb.className=\"tp-thumb\";\n    thumb.tabIndex=allowed?0:-1;\n    thumb.setAttribute(\"role\",\"button\");\n    thumb.setAttribute(\"aria-disabled\",String(!allowed));\n    thumb.setAttribute(\"aria-label\",allowed?\"Xem \"+video.title:\"Video tr\u1ea3 ph\u00ed: \"+video.title);\n    var image=document.createElement(\"img\");image.loading=\"lazy\";image.alt=\"\";\n    image.src=\"https://img.youtube.com/vi/\"+video.id+\"/hqdefault.jpg\";\n    var play=document.createElement(\"span\");play.className=\"tp-play\";\n    thumb.append(image,play);\n    thumb.addEventListener(\"click\",function(){requestVideo(video);});\n    thumb.addEventListener(\"keydown\",function(event){if(event.key===\"Enter\" || event.key===\" \"){event.preventDefault();requestVideo(video);}});\n    var info=document.createElement(\"div\");info.className=\"tp-v-info\";\n    var meta=document.createElement(\"div\");meta.className=\"tp-v-meta\";\n    var label=document.createElement(\"span\");label.className=\"tp-lesson\";\n    label.textContent=(video.kind===\"replay\"?\"BU\u1ed4I \":\"B\u00c0I \")+video.lesson;\n    var badge=document.createElement(\"span\");badge.className=\"tp-level-tag\";\n    badge.textContent=video.paid\n        ?\"Tr\u1ea3 ph\u00ed \"+String.fromCharCode(183)+(allowed?\" \u0111\u00e3 m\u1edf\":\" ch\u01b0a m\u1edf\")\n        :\"Mi\u1ec5n ph\u00ed\";\n    meta.append(label,badge);\n    var title=document.createElement(\"h3\");title.textContent=video.title;\n    var description=document.createElement(\"p\");description.textContent=video.description;\n    var button=document.createElement(\"button\");button.className=\"tp-watch\";button.type=\"button\";\n    button.disabled=!allowed;\n    button.textContent=allowed?\"Xem video \"+String.fromCharCode(8594):\"C\u1ea7n g\u00f3i n\u00e2ng c\u1ea5p\";\n    button.addEventListener(\"click\",function(){requestVideo(video);});\n    info.append(meta,title,description);\n    if(video.kind!==\"replay\"){\n        var level=document.createElement(\"p\");level.className=\"tp-section-note\";level.textContent=\"Rank khuy\u1ebfn ngh\u1ecb: \"+video.difficulty;info.appendChild(level);\n    }\n    info.appendChild(button);card.append(thumb,info);return card;\n}\n\n\nfunction renderPages(kind){\n    var replay=kind===\"replay\";\n    var box=id(replay?\"tpReplayPages\":\"tpVideoPages\");\n    var videos=replay?APP.replays:APP.videos;\n    var pageKey=replay?\"replayPage\":\"page\";\n    var count=Math.ceil(videos.length/APP.PAGE_SIZE);\n    box.innerHTML=\"\";box.style.display=count>1?\"flex\":\"none\";\n    if(count<=1) return;\n    var previous=document.createElement(\"button\"),next=document.createElement(\"button\"),label=document.createElement(\"span\");\n    previous.type=next.type=\"button\";previous.className=next.className=\"tp-page\";\n    previous.textContent=\"Trang tr\u01b0\u1edbc\";next.textContent=\"Trang sau\";\n    previous.disabled=APP[pageKey]===1;next.disabled=APP[pageKey]===count;\n    label.textContent=\"Trang \"+APP[pageKey]+\" / \"+count;\n    previous.onclick=function(){APP[pageKey]--;renderVideoList(kind);};\n    next.onclick=function(){APP[pageKey]++;renderVideoList(kind);};\n    box.append(previous,label,next);\n}\n\n\n/* =========================================================\n   VIDEO DIRECT TO YOUTUBE\n========================================================= */\n\nfunction requestVideo(x){\n    if(!canWatchVideo(x)) return;\n\n    if(\n        !x ||\n        !x.id\n    ){\n        return;\n    }\n\n\n    APP.currentVideo=x;\n\n    syncContext();\n\n\n    var p=\n        studentPoints();\n\n\n    if(\n        APP.loginMode!==\"student\" ||\n        p===null ||\n        p>=x.difficulty\n    ){\n\n        openYouTube(x);\n\n        return;\n    }\n\n\n    APP.pendingVideo=x;\n\n\n    id(\n        \"tpCurrentPoints\"\n    ).textContent=p;\n\n\n    id(\n        \"tpRequiredPoints\"\n    ).textContent=\n        x.difficulty;\n\n\n    id(\n        \"tpWarningText\"\n    ).textContent=\n        \"B\u1ea1n \u0111ang c\u00f3 \"+\n        p+\n        \" Rank, b\u00e0i h\u1ecdc n\u00e0y \u0111\u01b0\u1ee3c khuy\u1ebfn ngh\u1ecb t\u1eeb \"+\n        x.difficulty+\n        \" Rank.\";\n\n\n    id(\n        \"tpWarningModal\"\n    ).classList.add(\n        \"open\"\n    );\n}\n\n\nfunction openYouTube(x){\n    if(!canWatchVideo(x)) return;\n\n    if(\n        !x ||\n        !x.id\n    ){\n        return;\n    }\n\n\n    APP.currentVideo=x;\n\n    syncContext();\n\n\n    document.body.style.overflow=\"\";\n\n\n    var url=\n        \"https://www.youtube.com/watch?v=\"+\n        encodeURIComponent(\n            x.id\n        );\n\n\n    window.location.assign(url);\n}\n\n\nfunction watchAnyway(){\n\n    var x=\n        APP.pendingVideo;\n\n\n    id(\n        \"tpWarningModal\"\n    ).classList.remove(\n        \"open\"\n    );\n\n\n    APP.pendingVideo=null;\n\n    document.body.style.overflow=\"\";\n\n\n    if(x){\n        openYouTube(x);\n    }\n}\n\n\nfunction goPractice(){\n\n    closeWarning();\n\n    window.open(\n        APP.FORM,\n        \"_blank\",\n        \"noopener\"\n    );\n}\n\n\nfunction closeWarning(){\n\n    var modal=\n        id(\"tpWarningModal\");\n\n    if(modal){\n\n        modal.classList.remove(\n            \"open\"\n        );\n    }\n\n    APP.pendingVideo=null;\n    APP.currentVideo=null;\n\n    document.body.style.overflow=\"\";\n\n    syncContext();\n}\n\n\nfunction warningOutside(e){\n\n    if(\n        e.target===\n        id(\"tpWarningModal\")\n    ){\n        closeWarning();\n    }\n}\n\n\n/* =========================================================\n   QR\n========================================================= */\n\nfunction upgradeTransferInfo(){\n    var code=norm(APP.currentCode || APP.upgradeCode);\n    var input=id(\"tpUpgradePhone\");\n    var phone=input?String(input.value || \"\").replace(/\\D/g,\"\").substring(0,15):\"\";\n    if(input) input.value=phone;\n    return \"HOCTHUPHAP\"+(code?\" \"+code:\"\")+(phone?\" \"+phone:\"\");\n}\n\nfunction upgradeQrUrl(info){\n    return \"https://img.vietqr.io/image/MB-0530113118888-compact2.png\"+\n        \"?amount=800000&addInfo=\"+encodeURIComponent(info)+\n        \"&accountName=\"+encodeURIComponent(\"BUI KHAC SANG\");\n}\n\nfunction updateQR(){\n    var info=upgradeTransferInfo();\n    var syntax=id(\"tpTransferSyntax\"),image=id(\"tpQrImage\"),status=id(\"tpQrStatus\");\n    if(syntax) syntax.textContent=info;\n    if(image) image.src=upgradeQrUrl(info);\n    if(status) status.textContent=\"QR \u0111\u00e3 s\u1eb5n s\u00e0ng\"+(APP.currentCode || APP.upgradeCode?\" cho m\u00e3 \"+norm(APP.currentCode || APP.upgradeCode):\"\")+\".\";\n    document.querySelectorAll(\".tp-card-transfer-info\").forEach(function(node){node.textContent=info;});\n    document.querySelectorAll(\".tp-card-upgrade-qr\").forEach(function(node){node.src=upgradeQrUrl(info);});\n}\n\nfunction openUpgradePanel(){\n    var checkbox=id(\"tpUpgradeCheck\");\n    if(checkbox) checkbox.checked=true;\n    updateQR();\n}\n\nfunction syncUpgradeState(){\n    var checkbox=id(\"tpUpgradeCheck\");\n    if(checkbox) checkbox.checked=!hasPaidAccess();\n    updateQR();\n}\n\nfunction upgradePaymentCard(){\n    var panel=document.createElement(\"div\");panel.className=\"tp-card-payment\";\n    var title=document.createElement(\"strong\");title.textContent=\"Chuy\u1ec3n kho\u1ea3n n\u00e2ng c\u1ea5p t\u00e0i kho\u1ea3n\";panel.appendChild(title);\n    [[\"Ng\u00e2n h\u00e0ng\",\"MB Bank\"],[\"S\u1ed1 t\u00e0i kho\u1ea3n\",\"0530113118888\"],\n     [\"Ch\u1ee7 t\u00e0i kho\u1ea3n\",\"BUI KHAC SANG\"],[\"S\u1ed1 ti\u1ec1n\",\"800.000\u0111\"]].forEach(function(pair){\n        var row=document.createElement(\"div\");row.className=\"tp-card-payment-row\";\n        var label=document.createElement(\"span\"),value=document.createElement(\"strong\");\n        label.textContent=pair[0];value.textContent=pair[1];row.append(label,value);panel.appendChild(row);\n    });\n    var transferLabel=document.createElement(\"p\");transferLabel.textContent=\"N\u1ed9i dung chuy\u1ec3n kho\u1ea3n:\";\n    var transferInfo=document.createElement(\"strong\");transferInfo.className=\"tp-card-transfer-info\";transferInfo.textContent=upgradeTransferInfo();\n    var image=document.createElement(\"img\");image.className=\"tp-card-upgrade-qr\";\n    image.alt=\"M\u00e3 QR chuy\u1ec3n kho\u1ea3n n\u00e2ng c\u1ea5p t\u00e0i kho\u1ea3n h\u1ecdc vi\u00ean\";image.loading=\"lazy\";image.decoding=\"async\";\n    image.src=upgradeQrUrl(transferInfo.textContent);\n    var status=document.createElement(\"p\");status.className=\"tp-card-payment-note\";\n    status.textContent=\"Qu\u00e9t QR \u0111\u1ec3 chuy\u1ec3n kho\u1ea3n. Sau khi \u0111\u01b0\u1ee3c x\u00e1c nh\u1eadn v\u00e0o g\u00f3i n\u00e2ng c\u1ea5p, m\u00e3 h\u1ecdc vi\u00ean s\u1ebd \u0111\u01b0\u1ee3c m\u1edf video tr\u1ea3 ph\u00ed.\";\n    image.onerror=function(){image.style.display=\"none\";status.textContent=\"Ch\u01b0a t\u1ea3i \u0111\u01b0\u1ee3c QR. B\u1ea1n c\u00f3 th\u1ec3 chuy\u1ec3n kho\u1ea3n theo th\u00f4ng tin t\u00e0i kho\u1ea3n v\u00e0 n\u1ed9i dung b\u00ean tr\u00ean.\";};\n    panel.append(transferLabel,transferInfo,image,status);return panel;\n}\n\n\nvar qrT;\n\n\nfunction scheduleQR(){\n\n    clearTimeout(qrT);\n\n    qrT=\n        setTimeout(\n            updateQR,\n            250\n        );\n}\n\n\n/* =========================================================\n   MINH H\u1ed2NG CONTEXT\n========================================================= */\n\nfunction context(){\n\n    if(\n        APP.loginMode!==\"student\" ||\n        !APP.loginCompleted ||\n        !APP.currentCode\n    ){\n        return null;\n    }\n\n\n    var p=\n        APP.profile||{};\n\n\n    var r=\n        p.reward||{};\n\n\n    var v=\n        APP.currentVideo||\n        APP.pendingVideo;\n\n\n    var owned=\n        Array.isArray(\n            p.ownedItems\n        )\n        ?p.ownedItems\n        :[];\n\n\n    return{\n\n        page:\"ThuVien\",\n\n        studentCode:\n        APP.currentCode,\n\n        data:{\n\n            studentName:\n            trim(\n                p.name||\n                (\n                    APP.student &&\n                    APP.student.name\n                )\n            ),\n\n            group:\n            trim(\n                APP.student &&\n                APP.student.group\n            ),\n\n            course:\n            trim(\n                APP.student &&\n                APP.student.course\n            ),\n\n            rank:\n            Number(\n                p.points||0\n            ),\n\n            rankingPoints:\n            Number(\n                p.points||0\n            ),\n\n            title:\n            trim(p.title),\n\n            totalGems:\n            Number(\n                p.totalGems||0\n            ),\n\n            ownedItemTypes:\n            groupOwnedItemsForDisplay(\n                owned\n            ).length,\n\n            longestStreak:\n            Number(\n                r.longestStreak||0\n            ),\n\n            bestHighRun:\n            Number(\n                r.bestHighRun||0\n            ),\n\n            videoCount:\n            APP.videos.length+APP.replays.length,\n\n            replayVideoCount:APP.replays.length,\n            paidVideoAccess:hasPaidAccess(),\n\n            currentVideoTitle:\n            v\n            ?trim(v.title)\n            :\"\",\n\n            currentVideoLesson:\n            v\n            ?trim(v.lesson)\n            :\"\",\n\n            currentVideoDifficulty:\n            v\n            ?Number(\n                v.difficulty||0\n            )\n            :0\n        },\n\n        conditions:{\n\n            library_access:true,\n\n            profile_ready:\n            Boolean(\n                APP.profile\n            ),\n\n            has_rank:\n            Number(\n                p.points||0\n            )>0,\n\n            no_rank:\n            Number(\n                p.points||0\n            )<=0,\n\n            has_gems:\n            Number(\n                p.totalGems||0\n            )>0,\n\n            no_gems:\n            Number(\n                p.totalGems||0\n            )<=0,\n\n            has_items:\n            owned.length>0,\n\n            no_items:\n            owned.length===0,\n\n            viewing_video:\n            Boolean(v),\n\n            video_above_rank:\n            Boolean(\n                v &&\n                Number(\n                    p.points||0\n                )\n                <\n                Number(\n                    v.difficulty||0\n                )\n            ),\n\n            video_suitable_rank:\n            Boolean(\n                v &&\n                Number(\n                    p.points||0\n                )\n                >=\n                Number(\n                    v.difficulty||0\n                )\n            )\n        }\n    };\n}\n\n\nfunction syncContext(){\n\n    var a=\n        window.OCDMinhHongContext;\n\n    var p=\n        context();\n\n\n    if(\n        a &&\n        p &&\n        typeof a.set===\"function\"\n    ){\n\n        try{\n\n            a.set(\n                p,\n                \"thu-vien\"\n            );\n\n            return true;\n\n        }catch(e){}\n    }\n\n    return false;\n}\n\n\n/* =========================================================\n   EVENTS\n========================================================= */\n\nwindow.addEventListener(\n    \"ocdRewardProfileChanged\",\n    function(e){\n\n        var c=\n            norm(\n                e &&\n                e.detail &&\n                e.detail.code\n            );\n\n\n        if(\n            APP.loginMode===\"student\" &&\n            APP.loginCompleted &&\n            c===norm(\n                APP.currentCode\n            )\n        ){\n\n            loadProfile(true);\n        }\n    }\n);\n\n\nwindow.addEventListener(\n    \"ocdStudentSessionChanged\",\n    function(){\n\n        if(\n            !APP.loginCompleted\n        ){\n\n            var code=\n                getVerifiedMinhHongCode();\n\n\n            if(\n                code &&\n                code!==APP.autoLoginCode\n            ){\n\n                APP.autoLoginFinished=false;\n            }\n\n\n            tryAutoLoginFromMinhHong();\n\n        }else{\n\n            syncContext();\n        }\n    }\n);\n\n\ndocument.addEventListener(\n    \"keydown\",\n    function(e){\n\n        if(e.key===\"Escape\"){\n            closeWarning();\n        }\n    }\n);\n\n\n/* =========================================================\n   MOBILE SAFETY\n========================================================= */\n\ndocument.body.style.overflow=\"\";\n\n\n/* =========================================================\n   PRELOAD DIRECTORY\n========================================================= */\n\nsetTimeout(()=>{\n\n    ensureStudentDirectory(false)\n    .catch(\n        ()=>{}\n    );\n\n},120);\n\n\n/* =========================================================\n   AUTO LOGIN WATCHER\n========================================================= */\n\nfunction startAutoLoginWatcher(){\n\n    var tries=0;\n    var maxTries=80;\n\n\n    function check(){\n\n        if(APP.loginCompleted){\n            return;\n        }\n\n\n        tries++;\n\n\n        var code=\n            getVerifiedMinhHongCode();\n\n\n        if(code){\n\n            tryAutoLoginFromMinhHong();\n\n            return;\n        }\n\n\n        if(\n            tries<maxTries\n        ){\n\n            setTimeout(\n                check,\n                100\n            );\n        }\n    }\n\n\n    check();\n}\n\n\nsetTimeout(\n    startAutoLoginWatcher,\n    0\n);\n\n\n/* =========================================================\n   PUBLIC API\n========================================================= */\n\nwindow.OCDThuVienLibrary={\n\n    version:\n    \"TV4-4.0-canonical-items-avatar-auto-session\",\n\n    getCode:\n    ()=>APP.currentCode||\"\",\n\n    getStudent:\n    ()=>APP.student\n        ?Object.assign(\n            {},\n            APP.student\n        )\n        :null,\n\n    getRank:\n    ()=>APP.profile\n        ?Number(\n            APP.profile.points||0\n        )\n        :null,\n\n    getAvatar:\n    ()=>APP.profile\n        ?trim(\n            APP.profile.avatar\n        )\n        :\"\",\n\n    getOwnedItems:\n    ()=>APP.profile &&\n        Array.isArray(\n            APP.profile.ownedItems\n        )\n        ?APP.profile.ownedItems.slice()\n        :[],\n\n    getCurrentVideo:\n    ()=>APP.currentVideo\n        ?Object.assign(\n            {},\n            APP.currentVideo\n        )\n        :null,\n\n    getMinhHongContext:\n    context,\n\n    syncMinhHongContext:\n    syncContext,\n\n    refreshProfile:\n    ()=>loadProfile(true),\n\n    tryAutoLogin:\n    tryAutoLoginFromMinhHong\n};\n\n\n/* =========================================================\n   GLOBAL\n========================================================= */\n\nwindow.tpLogin=\n    login;\n\nwindow.tpPasswordKey=\n    passwordKey;\n\nwindow.tpUpdateQR=\n    updateQR;\n\nwindow.tpScheduleQR=\n    scheduleQR;\n\nwindow.tpWatchAnyway=\n    watchAnyway;\n\nwindow.tpGoPractice=\n    goPractice;\n\nwindow.tpCloseWarning=\n    closeWarning;\n\nwindow.tpWarningOutside=\n    warningOutside;\n\n\nconsole.log(\n    \"KHO TAI LIEU TV4 - CANONICAL ITEMS + AVATAR + MINH HONG AUTO LOGIN READY\"\n);\n\n})();\n\n</script>\n\n</div>");})();
